INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_civil_lease','民法典租赁合同资料摘要','民法典租赁','全国人大','2021-01-01','现行有效','整理租赁合同、维修、转租和返还的一般规则。');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_privacy','个人信息保护资料摘要','个人信息保护','全国人大','2021-11-01','现行有效','整理个人信息处理的必要性、授权和最小范围。');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_beijing_rental','北京住房租赁管理资料汇编','北京租赁管理','北京市有关部门','2022-09-01','现行有效','汇总住房租赁登记、经纪服务和资金风险提示。');
INSERT INTO statutes(statute_id,name,short_name,issuer,effective_date,status,summary) VALUES ('stat_property','物业服务与房屋维修资料摘要','物业与维修','有关部门','2021-01-01','现行有效','整理公共部位、专有部位和报修证据的常见处理口径。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_written','stat_civil_lease','租赁-书面合同',1,'合同内容','租赁期限、租金、押金、维修、返还和违约事项宜在书面合同中明确。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_repair','stat_civil_lease','租赁-维修',2,'维修义务','设施故障应结合合同约定、故障原因、报修记录和维修凭证判断责任。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_deposit','stat_civil_lease','租赁-押金',3,'押金返还','押金用途、抵扣顺序、返还时间和扣款凭证应有明确约定。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_lease_transfer','stat_civil_lease','租赁-转租',4,'出租权限','出租人或受托经纪人的出租权限应能够核实。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_privacy_min','stat_privacy','个人信息-最小必要',1,'最小范围','身份证、收入证明等资料的收集应与明确目的相匹配。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_privacy_auth','stat_privacy','个人信息-授权',2,'授权记录','对外发送敏感材料应保留具体对象、用途和范围的授权记录。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_bj_broker','stat_beijing_rental','北京租赁-经纪服务',1,'经纪主体','经纪机构、从业人员和收费项目应可核验并在合同中列示。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_bj_payment','stat_beijing_rental','北京租赁-资金',2,'支付路径','租金、押金和服务费应通过可追溯渠道支付并保存凭证。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_bj_registration','stat_beijing_rental','北京租赁-登记',3,'租赁登记','租赁登记材料和办理责任可由合同约定并按实际要求准备。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_property_common','stat_property','物业-公共部位',1,'公共维修','外墙、屋面和公共管线问题通常需结合物业职责和专项维修记录判断。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_property_private','stat_property','物业-专有部位',2,'室内设施','室内设备维修需区分自然损耗、使用原因和合同约定。');
INSERT INTO statute_articles(article_id,statute_id,article_no,seq,heading,text) VALUES ('art_property_evidence','stat_property','物业-报修证据',3,'工单证据','报修时间、照片、检测结论、维修报价和回访记录可用于还原责任。');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_09cc63e5f4','（2022）京仲1000号','张某与安居住房服务有限公司押金返还纠纷','court_bjac','合同纠纷','押金返还','2022-01-05','张某、安居住房服务有限公司','张某与安居住房服务有限公司因押金返还发生争议。退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围。主要证据为租客提交入住照片、退租视频和保洁票据。','退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围。庭审材料显示，租客提交入住照片、退租视频和保洁票据。双方对合同相关条款的解释不一致。','押金返还应先看合同约定，再核对实际付款、退款条件和金额凭证。租客提交入住照片、退租视频和保洁票据。','对有书面凭证支持的押金返还主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,押金返还,书面证据,租客提交入住照片、退租视频和保洁票据');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_874029012c','（2022）京民初1037号','李某与明远资产管理有限公司噪声影响纠纷','court_cp','合同纠纷','噪声影响','2022-01-28','李某、明远资产管理有限公司','本案处理噪声影响问题：出租前未披露相邻施工，租客入住后主张影响正常居住；庭审中提交了施工公告和看房时间能够证明披露范围。','出租前未披露相邻施工，租客入住后主张影响正常居住。庭审材料显示，施工公告和看房时间能够证明披露范围。双方对合同相关条款的解释不一致。','法院结合物业公告、现场路线和新增费用审查噪声影响，其中施工公告和看房时间能够证明披露范围。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,噪声影响,书面证据,施工公告和看房时间能够证明披露范围');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_d68cc03806','（2022）京民初1074号','王某与京北房屋经纪有限公司租金调整纠纷','court_sjs','合同纠纷','租金调整','2022-02-20','王某、京北房屋经纪有限公司','京北房屋经纪有限公司与王某对租金调整的责任范围意见不一。查明事实为续租报价在短期内多次变化，租客主张应按较早报价履行，证据包括邮件中未出现明确接受或签署记录。','续租报价在短期内多次变化，租客主张应按较早报价履行。庭审材料显示，邮件中未出现明确接受或签署记录。双方对合同相关条款的解释不一致。','主张租金调整的一方需说明计算方式和合同依据；现有证据中，邮件中未出现明确接受或签署记录。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,租金调整,书面证据,邮件中未出现明确接受或签署记录');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_d514861057','（2022）京民初1111号','赵某与瑞景物业管理有限公司搬家通道纠纷','court_hd','其他','搬家通道','2022-03-15','赵某、瑞景物业管理有限公司','争议源于物业临时封闭车库通道，租客增加搬运费用。赵某据此主张处理搬家通道，并提交公告发布时间晚于搬家公司预约时间。','物业临时封闭车库通道，租客增加搬运费用。庭审材料显示，公告发布时间晚于搬家公司预约时间。双方对合同相关条款的解释不一致。','判断搬家通道是否影响合同履行，需要比较看房时披露内容、公告时间和实际通行情况。公告发布时间晚于搬家公司预约时间。','双方应按合同及已核实履行事实承担相应责任。','部分支持赵某的请求，具体金额以判决主文为准。','部分支持','租赁,搬家通道,书面证据,公告发布时间晚于搬家公司预约时间');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b1d774263a','（2022）京民初1148号','陈某与海淀住房租赁管理有限公司出租权限纠纷','court_xc','合同纠纷','出租权限','2022-04-07','陈某、海淀住房租赁管理有限公司','围绕出租权限，双方确认租赁关系存在，但对费用和责任有分歧。签约人并非产权登记人，双方争议其是否取得有效委托；委托书、产权材料和收款账户是争议焦点。','签约人并非产权登记人，双方争议其是否取得有效委托。庭审材料显示，委托书、产权材料和收款账户是争议焦点。双方对合同相关条款的解释不一致。','法院核对主体身份、授权文件和资料用途后处理出租权限；委托书、产权材料和收款账户是争议焦点。','经调解，双方就出租权限的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,出租权限,书面证据,委托书、产权材料和收款账户是争议焦点');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_83478d5bd5','（2022）京民终1185号','周某与清河物业服务中心个人信息纠纷','court_bj2','侵权责任','个人信息','2022-04-30','周某、清河物业服务中心','周某起诉要求解决个人信息。案件材料记载经纪人要求提前发送身份证和收入证明，租客质疑收集范围，其中机构未能说明资料保存期限和接收人员。','经纪人要求提前发送身份证和收入证明，租客质疑收集范围。庭审材料显示，机构未能说明资料保存期限和接收人员。双方对合同相关条款的解释不一致。','对于个人信息，不能只凭口头说明，应结合可追溯的书面材料。现有材料表明，机构未能说明资料保存期限和接收人员。','对有书面凭证支持的个人信息主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,个人信息,书面证据,机构未能说明资料保存期限和接收人员');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_5da61cfcd5','（2022）京民初1222号','孙某与诚家房地产经纪中心电器折旧纠纷','court_cy','合同纠纷','电器折旧','2022-05-23','孙某、诚家房地产经纪中心','电器折旧是本案主要争点。空调压缩机故障后出租方要求租客承担全部更换费，双方分别就检测报告认为设备已接近设计寿命发表意见。','空调压缩机故障后出租方要求租客承担全部更换费。庭审材料显示，检测报告认为设备已接近设计寿命。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断电器折旧责任。检测报告认为设备已接近设计寿命。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,电器折旧,书面证据,检测报告认为设备已接近设计寿命');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_a9ed5c3d9a','（2022）京民初1259号','刘某与上地公寓运营中心维修垫付纠纷','court_ft','合同纠纷','维修垫付','2022-06-15','刘某、上地公寓运营中心','案件发生在租赁履行期间。热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议；与维修垫付相关的材料包括报修工单显示故障发生后当天通知房东。','热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议。庭审材料显示，报修工单显示故障发生后当天通知房东。双方对合同相关条款的解释不一致。','处理维修垫付需要区分自然损耗、公共部位责任和不当使用。现有材料显示，报修工单显示故障发生后当天通知房东。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,维修垫付,书面证据,报修工单显示故障发生后当天通知房东');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_9cd8528a41','（2022）京仲1296号','高某与安居住房服务有限公司门禁变更纠纷','court_bjac','其他','门禁变更','2022-07-08','高某、安居住房服务有限公司','高某与安居住房服务有限公司对门禁变更协商未果。已查明小区夜间关闭部分入口，租客认为通勤条件明显变化，并有物业公告说明入口调整属于阶段性管理措施佐证。','小区夜间关闭部分入口，租客认为通勤条件明显变化。庭审材料显示，物业公告说明入口调整属于阶段性管理措施。双方对合同相关条款的解释不一致。','门禁变更的责任范围取决于变化是否可预见以及是否造成实际损失；物业公告说明入口调整属于阶段性管理措施。','双方应按合同及已核实履行事实承担相应责任。','部分支持高某的请求，具体金额以判决主文为准。','部分支持','租赁,门禁变更,书面证据,物业公告说明入口调整属于阶段性管理措施');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_62237d39ad','（2022）京民初1333号','林某与明远资产管理有限公司付款账户纠纷','court_cp','合同纠纷','付款账户','2022-07-31','林某、明远资产管理有限公司','法院审理的核心是付款账户。出租方临时要求改向个人账户付款，租客拒绝后产生争议，现有书面材料中包含原合同和历史流水均指向另一账户。','出租方临时要求改向个人账户付款，租客拒绝后产生争议。庭审材料显示，原合同和历史流水均指向另一账户。双方对合同相关条款的解释不一致。','付款账户应先看合同约定，再核对实际付款、退款条件和金额凭证。原合同和历史流水均指向另一账户。','经调解，双方就付款账户的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,付款账户,书面证据,原合同和历史流水均指向另一账户');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_3194ee337a','（2022）京民初1370号','许某与京北房屋经纪有限公司租期衔接纠纷','court_sjs','合同纠纷','租期衔接','2022-08-23','许某、京北房屋经纪有限公司','双方合同履行过程中出现租期衔接争议。新租约起始日与旧租约终止日重叠；证据链以双方对钥匙和租金按日结算未达成一致为主。','新租约起始日与旧租约终止日重叠。庭审材料显示，双方对钥匙和租金按日结算未达成一致。双方对合同相关条款的解释不一致。','法院围绕租期衔接审查书面条款、沟通时间和资金流，注意到双方对钥匙和租金按日结算未达成一致。','对有书面凭证支持的租期衔接主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,租期衔接,书面证据,双方对钥匙和租金按日结算未达成一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b333e85762','（2022）京民初1407号','韩某与瑞景物业管理有限公司家具损坏纠纷','court_hd','合同纠纷','家具损坏','2022-09-15','韩某、瑞景物业管理有限公司','该案涉及家具损坏及相应费用承担。退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用，提交的关键材料为交接照片显示铰链此前已有松动。','退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。庭审材料显示，交接照片显示铰链此前已有松动。双方对合同相关条款的解释不一致。','关于家具损坏，工单、检测报告和现场照片比单方陈述更能还原经过；交接照片显示铰链此前已有松动。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,家具损坏,书面证据,交接照片显示铰链此前已有松动');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_5e84d301c9','（2022）京民初1444号','杜某与海淀住房租赁管理有限公司物业维修纠纷','court_xc','其他','物业维修','2022-10-08','杜某、海淀住房租赁管理有限公司','杜某与海淀住房租赁管理有限公司因物业维修发生争议。公共排水堵塞造成室内返水，物业与出租方争议责任分担。主要证据为维修记录显示堵点位于公共立管。','公共排水堵塞造成室内返水，物业与出租方争议责任分担。庭审材料显示，维修记录显示堵点位于公共立管。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断物业维修责任。维修记录显示堵点位于公共立管。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,物业维修,书面证据,维修记录显示堵点位于公共立管');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_18e9318967','（2022）京民终1481号','顾某与清河物业服务中心转租授权纠纷','court_bj2','合同纠纷','转租授权','2022-10-31','顾某、清河物业服务中心','本案处理转租授权问题：二房东签约后无法提供原出租人的转租同意；庭审中提交了主合同中存在禁止转租条款。','二房东签约后无法提供原出租人的转租同意。庭审材料显示，主合同中存在禁止转租条款。双方对合同相关条款的解释不一致。','法院核对主体身份、授权文件和资料用途后处理转租授权；主合同中存在禁止转租条款。','双方应按合同及已核实履行事实承担相应责任。','部分支持顾某的请求，具体金额以判决主文为准。','部分支持','租赁,转租授权,书面证据,主合同中存在禁止转租条款');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_2c40600c20','（2022）京民初1518号','叶某与诚家房地产经纪中心经纪服务费纠纷','court_cy','合同纠纷','经纪服务费','2022-11-23','叶某、诚家房地产经纪中心','诚家房地产经纪中心与叶某对经纪服务费的责任范围意见不一。查明事实为经纪人在签约前后对服务费口径表述不一致，证据包括平台页面和聊天记录显示收费项目发生变化。','经纪人在签约前后对服务费口径表述不一致。庭审材料显示，平台页面和聊天记录显示收费项目发生变化。双方对合同相关条款的解释不一致。','主张经纪服务费的一方需说明计算方式和合同依据；现有证据中，平台页面和聊天记录显示收费项目发生变化。','经调解，双方就经纪服务费的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,经纪服务费,书面证据,平台页面和聊天记录显示收费项目发生变化');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_906a7213c3','（2022）京民初1555号','唐某与上地公寓运营中心定金性质纠纷','court_ft','合同纠纷','定金性质','2022-12-16','唐某、上地公寓运营中心','争议源于付款备注写作意向金，收据写作定金，双方争议退款条件。唐某据此主张处理定金性质，并提交付款前后文本对款项用途表述不一致。','付款备注写作意向金，收据写作定金，双方争议退款条件。庭审材料显示，付款前后文本对款项用途表述不一致。双方对合同相关条款的解释不一致。','定金性质应先看合同约定，再核对实际付款、退款条件和金额凭证。付款前后文本对款项用途表述不一致。','对有书面凭证支持的定金性质主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,定金性质,书面证据,付款前后文本对款项用途表述不一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_cd99f7194f','（2023）京仲1592号','张某与安居住房服务有限公司清洁费用纠纷','court_bjac','合同纠纷','清洁费用','2023-01-08','张某、安居住房服务有限公司','围绕清洁费用，双方确认租赁关系存在，但对费用和责任有分歧。合同只写恢复整洁，退租时出租方主张高额深度清洁费；出租方未提供实际清洁发票。','合同只写恢复整洁，退租时出租方主张高额深度清洁费。庭审材料显示，出租方未提供实际清洁发票。双方对合同相关条款的解释不一致。','法院围绕清洁费用审查书面条款、沟通时间和资金流，注意到出租方未提供实际清洁发票。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,清洁费用,书面证据,出租方未提供实际清洁发票');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_2971130ee4','（2023）京民初1629号','李某与明远资产管理有限公司押金返还纠纷','court_xc','合同纠纷','押金返还','2023-01-31','李某、明远资产管理有限公司','李某起诉要求解决押金返还。案件材料记载退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围，其中租客提交入住照片、退租视频和保洁票据。','退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围。庭审材料显示，租客提交入住照片、退租视频和保洁票据。双方对合同相关条款的解释不一致。','主张押金返还的一方需说明计算方式和合同依据；现有证据中，租客提交入住照片、退租视频和保洁票据。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,押金返还,书面证据,租客提交入住照片、退租视频和保洁票据');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_c427ed19d0','（2023）京民终1666号','王某与京北房屋经纪有限公司噪声影响纠纷','court_bj2','合同纠纷','噪声影响','2023-02-23','王某、京北房屋经纪有限公司','噪声影响是本案主要争点。出租前未披露相邻施工，租客入住后主张影响正常居住，双方分别就施工公告和看房时间能够证明披露范围发表意见。','出租前未披露相邻施工，租客入住后主张影响正常居住。庭审材料显示，施工公告和看房时间能够证明披露范围。双方对合同相关条款的解释不一致。','判断噪声影响是否影响合同履行，需要比较看房时披露内容、公告时间和实际通行情况。施工公告和看房时间能够证明披露范围。','双方应按合同及已核实履行事实承担相应责任。','部分支持王某的请求，具体金额以判决主文为准。','部分支持','租赁,噪声影响,书面证据,施工公告和看房时间能够证明披露范围');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_772add5ff1','（2023）京民初1703号','赵某与瑞景物业管理有限公司租金调整纠纷','court_cy','合同纠纷','租金调整','2023-03-18','赵某、瑞景物业管理有限公司','案件发生在租赁履行期间。续租报价在短期内多次变化，租客主张应按较早报价履行；与租金调整相关的材料包括邮件中未出现明确接受或签署记录。','续租报价在短期内多次变化，租客主张应按较早报价履行。庭审材料显示，邮件中未出现明确接受或签署记录。双方对合同相关条款的解释不一致。','法院围绕租金调整审查书面条款、沟通时间和资金流，注意到邮件中未出现明确接受或签署记录。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,租金调整,书面证据,邮件中未出现明确接受或签署记录');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_79aad241c2','（2023）京民初1740号','陈某与海淀住房租赁管理有限公司搬家通道纠纷','court_ft','其他','搬家通道','2023-04-10','陈某、海淀住房租赁管理有限公司','陈某与海淀住房租赁管理有限公司对搬家通道协商未果。已查明物业临时封闭车库通道，租客增加搬运费用，并有公告发布时间晚于搬家公司预约时间佐证。','物业临时封闭车库通道，租客增加搬运费用。庭审材料显示，公告发布时间晚于搬家公司预约时间。双方对合同相关条款的解释不一致。','搬家通道的责任范围取决于变化是否可预见以及是否造成实际损失；公告发布时间晚于搬家公司预约时间。','双方应按合同及已核实履行事实承担相应责任。','部分支持陈某的请求，具体金额以判决主文为准。','部分支持','租赁,搬家通道,书面证据,公告发布时间晚于搬家公司预约时间');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_17dbcd34eb','（2023）京仲1777号','周某与清河物业服务中心出租权限纠纷','court_bjac','合同纠纷','出租权限','2023-05-03','周某、清河物业服务中心','法院审理的核心是出租权限。签约人并非产权登记人，双方争议其是否取得有效委托，现有书面材料中包含委托书、产权材料和收款账户是争议焦点。','签约人并非产权登记人，双方争议其是否取得有效委托。庭审材料显示，委托书、产权材料和收款账户是争议焦点。双方对合同相关条款的解释不一致。','出租权限取决于授权范围、材料来源和接收主体是否清楚。委托书、产权材料和收款账户是争议焦点。','经调解，双方就出租权限的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,出租权限,书面证据,委托书、产权材料和收款账户是争议焦点');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_054f5bbf5d','（2023）京民初1814号','孙某与诚家房地产经纪中心租赁登记纠纷','court_cp','合同纠纷','租赁登记','2023-05-26','孙某、诚家房地产经纪中心','双方合同履行过程中出现租赁登记争议。合同未约定由谁准备登记材料，入住后双方相互推诿；证据链以社区窗口清单能够说明所需材料为主。','合同未约定由谁准备登记材料，入住后双方相互推诿。庭审材料显示，社区窗口清单能够说明所需材料。双方对合同相关条款的解释不一致。','法院核对主体身份、授权文件和资料用途后处理租赁登记；社区窗口清单能够说明所需材料。','对有书面凭证支持的租赁登记主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,租赁登记,书面证据,社区窗口清单能够说明所需材料');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_32f70cb2c1','（2023）京民初1851号','刘某与上地公寓运营中心看房承诺纠纷','court_sjs','合同纠纷','看房承诺','2023-06-18','刘某、上地公寓运营中心','该案涉及看房承诺及相应费用承担。经纪人口头承诺可养宠物，合同草案却明确禁止，提交的关键材料为录音、平台详情和草案内容彼此冲突。','经纪人口头承诺可养宠物，合同草案却明确禁止。庭审材料显示，录音、平台详情和草案内容彼此冲突。双方对合同相关条款的解释不一致。','看房承诺不能只依据一方回忆，应由交接单、录音或平台页面相互印证；录音、平台详情和草案内容彼此冲突。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,看房承诺,书面证据,录音、平台详情和草案内容彼此冲突');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_1781f02a67','（2023）京民初1888号','高某与安居住房服务有限公司外墙渗水纠纷','court_hd','合同纠纷','外墙渗水','2023-07-11','高某、安居住房服务有限公司','高某与安居住房服务有限公司因外墙渗水发生争议。暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关。主要证据为物业工单、气象记录和墙面照片能够相互印证。','暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关。庭审材料显示，物业工单、气象记录和墙面照片能够相互印证。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断外墙渗水责任。物业工单、气象记录和墙面照片能够相互印证。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,外墙渗水,书面证据,物业工单、气象记录和墙面照片能够相互印证');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_eed811f448','（2023）京民初1925号','林某与明远资产管理有限公司供暖结算纠纷','court_xc','合同纠纷','供暖结算','2023-08-03','林某、明远资产管理有限公司','本案处理供暖结算问题：租期跨越供暖季，预收供暖费的退还方式没有写清；庭审中提交了缴费凭证和合同附件对结算周期记载不同。','租期跨越供暖季，预收供暖费的退还方式没有写清。庭审材料显示，缴费凭证和合同附件对结算周期记载不同。双方对合同相关条款的解释不一致。','法院围绕供暖结算审查书面条款、沟通时间和资金流，注意到缴费凭证和合同附件对结算周期记载不同。','双方应按合同及已核实履行事实承担相应责任。','部分支持林某的请求，具体金额以判决主文为准。','部分支持','租赁,供暖结算,书面证据,缴费凭证和合同附件对结算周期记载不同');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_7d8265e019','（2023）京民终1962号','许某与京北房屋经纪有限公司钥匙交接纠纷','court_bj2','合同纠纷','钥匙交接','2023-08-26','许某、京北房屋经纪有限公司','京北房屋经纪有限公司与许某对钥匙交接的责任范围意见不一。查明事实为交房时钥匙数量与退租清单不一致，证据包括双方签字的交接单只列明三把钥匙。','交房时钥匙数量与退租清单不一致。庭审材料显示，双方签字的交接单只列明三把钥匙。双方对合同相关条款的解释不一致。','钥匙交接不能只依据一方回忆，应由交接单、录音或平台页面相互印证；双方签字的交接单只列明三把钥匙。','经调解，双方就钥匙交接的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,钥匙交接,书面证据,双方签字的交接单只列明三把钥匙');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_320f302d76','（2023）京民初1999号','韩某与瑞景物业管理有限公司发票开具纠纷','court_cy','合同纠纷','发票开具','2023-09-18','韩某、瑞景物业管理有限公司','争议源于机构收取服务费后长期未开具发票。韩某据此主张处理发票开具，并提交付款记录和多次催办邮件可以核实。','机构收取服务费后长期未开具发票。庭审材料显示，付款记录和多次催办邮件可以核实。双方对合同相关条款的解释不一致。','发票开具应先看合同约定，再核对实际付款、退款条件和金额凭证。付款记录和多次催办邮件可以核实。','对有书面凭证支持的发票开具主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,发票开具,书面证据,付款记录和多次催办邮件可以核实');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_7fbb72dee6','（2023）京民初2036号','杜某与海淀住房租赁管理有限公司家具损坏纠纷','court_ft','合同纠纷','家具损坏','2023-10-11','杜某、海淀住房租赁管理有限公司','围绕家具损坏，双方确认租赁关系存在，但对费用和责任有分歧。退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用；交接照片显示铰链此前已有松动。','退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。庭审材料显示，交接照片显示铰链此前已有松动。双方对合同相关条款的解释不一致。','处理家具损坏需要区分自然损耗、公共部位责任和不当使用。现有材料显示，交接照片显示铰链此前已有松动。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,家具损坏,书面证据,交接照片显示铰链此前已有松动');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_cc84f48583','（2023）京仲2073号','顾某与清河物业服务中心物业维修纠纷','court_bjac','其他','物业维修','2023-11-03','顾某、清河物业服务中心','顾某起诉要求解决物业维修。案件材料记载公共排水堵塞造成室内返水，物业与出租方争议责任分担，其中维修记录显示堵点位于公共立管。','公共排水堵塞造成室内返水，物业与出租方争议责任分担。庭审材料显示，维修记录显示堵点位于公共立管。双方对合同相关条款的解释不一致。','关于物业维修，工单、检测报告和现场照片比单方陈述更能还原经过；维修记录显示堵点位于公共立管。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,物业维修,书面证据,维修记录显示堵点位于公共立管');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_30cd36e2be','（2023）京民初2110号','叶某与诚家房地产经纪中心转租授权纠纷','court_cp','合同纠纷','转租授权','2023-11-26','叶某、诚家房地产经纪中心','转租授权是本案主要争点。二房东签约后无法提供原出租人的转租同意，双方分别就主合同中存在禁止转租条款发表意见。','二房东签约后无法提供原出租人的转租同意。庭审材料显示，主合同中存在禁止转租条款。双方对合同相关条款的解释不一致。','转租授权取决于授权范围、材料来源和接收主体是否清楚。主合同中存在禁止转租条款。','双方应按合同及已核实履行事实承担相应责任。','部分支持叶某的请求，具体金额以判决主文为准。','部分支持','租赁,转租授权,书面证据,主合同中存在禁止转租条款');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_d69ead22cc','（2023）京民初2147号','唐某与上地公寓运营中心经纪服务费纠纷','court_sjs','合同纠纷','经纪服务费','2023-12-19','唐某、上地公寓运营中心','案件发生在租赁履行期间。经纪人在签约前后对服务费口径表述不一致；与经纪服务费相关的材料包括平台页面和聊天记录显示收费项目发生变化。','经纪人在签约前后对服务费口径表述不一致。庭审材料显示，平台页面和聊天记录显示收费项目发生变化。双方对合同相关条款的解释不一致。','法院围绕经纪服务费审查书面条款、沟通时间和资金流，注意到平台页面和聊天记录显示收费项目发生变化。','经调解，双方就经纪服务费的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,经纪服务费,书面证据,平台页面和聊天记录显示收费项目发生变化');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_a3277aa7a2','（2024）京民初2184号','张某与安居住房服务有限公司定金性质纠纷','court_hd','合同纠纷','定金性质','2024-01-11','张某、安居住房服务有限公司','张某与安居住房服务有限公司对定金性质协商未果。已查明付款备注写作意向金，收据写作定金，双方争议退款条件，并有付款前后文本对款项用途表述不一致佐证。','付款备注写作意向金，收据写作定金，双方争议退款条件。庭审材料显示，付款前后文本对款项用途表述不一致。双方对合同相关条款的解释不一致。','主张定金性质的一方需说明计算方式和合同依据；现有证据中，付款前后文本对款项用途表述不一致。','对有书面凭证支持的定金性质主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,定金性质,书面证据,付款前后文本对款项用途表述不一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_5e9f5de900','（2024）京民初2221号','李某与明远资产管理有限公司电器折旧纠纷','court_xc','合同纠纷','电器折旧','2024-02-03','李某、明远资产管理有限公司','法院审理的核心是电器折旧。空调压缩机故障后出租方要求租客承担全部更换费，现有书面材料中包含检测报告认为设备已接近设计寿命。','空调压缩机故障后出租方要求租客承担全部更换费。庭审材料显示，检测报告认为设备已接近设计寿命。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断电器折旧责任。检测报告认为设备已接近设计寿命。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,电器折旧,书面证据,检测报告认为设备已接近设计寿命');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_06c5077762','（2024）京仲2258号','王某与京北房屋经纪有限公司维修垫付纠纷','court_bjac','合同纠纷','维修垫付','2024-02-26','王某、京北房屋经纪有限公司','双方合同履行过程中出现维修垫付争议。热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议；证据链以报修工单显示故障发生后当天通知房东为主。','热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议。庭审材料显示，报修工单显示故障发生后当天通知房东。双方对合同相关条款的解释不一致。','处理维修垫付需要区分自然损耗、公共部位责任和不当使用。现有材料显示，报修工单显示故障发生后当天通知房东。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,维修垫付,书面证据,报修工单显示故障发生后当天通知房东');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_bb63576f47','（2024）京民初2295号','赵某与瑞景物业管理有限公司门禁变更纠纷','court_cp','其他','门禁变更','2024-03-20','赵某、瑞景物业管理有限公司','该案涉及门禁变更及相应费用承担。小区夜间关闭部分入口，租客认为通勤条件明显变化，提交的关键材料为物业公告说明入口调整属于阶段性管理措施。','小区夜间关闭部分入口，租客认为通勤条件明显变化。庭审材料显示，物业公告说明入口调整属于阶段性管理措施。双方对合同相关条款的解释不一致。','门禁变更的责任范围取决于变化是否可预见以及是否造成实际损失；物业公告说明入口调整属于阶段性管理措施。','双方应按合同及已核实履行事实承担相应责任。','部分支持赵某的请求，具体金额以判决主文为准。','部分支持','租赁,门禁变更,书面证据,物业公告说明入口调整属于阶段性管理措施');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_0b6b36ce29','（2024）京民初2332号','陈某与海淀住房租赁管理有限公司付款账户纠纷','court_sjs','合同纠纷','付款账户','2024-04-12','陈某、海淀住房租赁管理有限公司','陈某与海淀住房租赁管理有限公司因付款账户发生争议。出租方临时要求改向个人账户付款，租客拒绝后产生争议。主要证据为原合同和历史流水均指向另一账户。','出租方临时要求改向个人账户付款，租客拒绝后产生争议。庭审材料显示，原合同和历史流水均指向另一账户。双方对合同相关条款的解释不一致。','付款账户应先看合同约定，再核对实际付款、退款条件和金额凭证。原合同和历史流水均指向另一账户。','经调解，双方就付款账户的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,付款账户,书面证据,原合同和历史流水均指向另一账户');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_ff1706f41f','（2024）京民初2369号','周某与清河物业服务中心租期衔接纠纷','court_hd','合同纠纷','租期衔接','2024-05-05','周某、清河物业服务中心','本案处理租期衔接问题：新租约起始日与旧租约终止日重叠；庭审中提交了双方对钥匙和租金按日结算未达成一致。','新租约起始日与旧租约终止日重叠。庭审材料显示，双方对钥匙和租金按日结算未达成一致。双方对合同相关条款的解释不一致。','法院围绕租期衔接审查书面条款、沟通时间和资金流，注意到双方对钥匙和租金按日结算未达成一致。','对有书面凭证支持的租期衔接主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,租期衔接,书面证据,双方对钥匙和租金按日结算未达成一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_8fee627b38','（2024）京民初2406号','孙某与诚家房地产经纪中心提前解约纠纷','court_xc','合同纠纷','提前解约','2024-05-28','孙某、诚家房地产经纪中心','诚家房地产经纪中心与孙某对提前解约的责任范围意见不一。查明事实为租客因工作地点变化提前退租，合同约定与补充协议表述不一致，证据包括双方邮件对解约通知期有不同理解。','租客因工作地点变化提前退租，合同约定与补充协议表述不一致。庭审材料显示，双方邮件对解约通知期有不同理解。双方对合同相关条款的解释不一致。','主张提前解约的一方需说明计算方式和合同依据；现有证据中，双方邮件对解约通知期有不同理解。','经调解，双方就提前解约的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,提前解约,书面证据,双方邮件对解约通知期有不同理解');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_ed24e944b1','（2024）京民终2443号','刘某与上地公寓运营中心租赁登记纠纷','court_bj2','合同纠纷','租赁登记','2024-06-20','刘某、上地公寓运营中心','争议源于合同未约定由谁准备登记材料，入住后双方相互推诿。刘某据此主张处理租赁登记，并提交社区窗口清单能够说明所需材料。','合同未约定由谁准备登记材料，入住后双方相互推诿。庭审材料显示，社区窗口清单能够说明所需材料。双方对合同相关条款的解释不一致。','租赁登记取决于授权范围、材料来源和接收主体是否清楚。社区窗口清单能够说明所需材料。','对有书面凭证支持的租赁登记主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,租赁登记,书面证据,社区窗口清单能够说明所需材料');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_3c1b5d3a22','（2024）京民初2480号','高某与安居住房服务有限公司看房承诺纠纷','court_cy','合同纠纷','看房承诺','2024-07-13','高某、安居住房服务有限公司','围绕看房承诺，双方确认租赁关系存在，但对费用和责任有分歧。经纪人口头承诺可养宠物，合同草案却明确禁止；录音、平台详情和草案内容彼此冲突。','经纪人口头承诺可养宠物，合同草案却明确禁止。庭审材料显示，录音、平台详情和草案内容彼此冲突。双方对合同相关条款的解释不一致。','法院围绕看房承诺核对承诺形成时间及书面记录，现有材料显示，录音、平台详情和草案内容彼此冲突。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,看房承诺,书面证据,录音、平台详情和草案内容彼此冲突');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_79f14360e5','（2024）京民初2517号','林某与明远资产管理有限公司外墙渗水纠纷','court_ft','合同纠纷','外墙渗水','2024-08-05','林某、明远资产管理有限公司','林某起诉要求解决外墙渗水。案件材料记载暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关，其中物业工单、气象记录和墙面照片能够相互印证。','暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关。庭审材料显示，物业工单、气象记录和墙面照片能够相互印证。双方对合同相关条款的解释不一致。','关于外墙渗水，工单、检测报告和现场照片比单方陈述更能还原经过；物业工单、气象记录和墙面照片能够相互印证。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,外墙渗水,书面证据,物业工单、气象记录和墙面照片能够相互印证');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_d7ca3f209f','（2024）京仲2554号','许某与京北房屋经纪有限公司供暖结算纠纷','court_bjac','合同纠纷','供暖结算','2024-08-28','许某、京北房屋经纪有限公司','供暖结算是本案主要争点。租期跨越供暖季，预收供暖费的退还方式没有写清，双方分别就缴费凭证和合同附件对结算周期记载不同发表意见。','租期跨越供暖季，预收供暖费的退还方式没有写清。庭审材料显示，缴费凭证和合同附件对结算周期记载不同。双方对合同相关条款的解释不一致。','供暖结算应先看合同约定，再核对实际付款、退款条件和金额凭证。缴费凭证和合同附件对结算周期记载不同。','双方应按合同及已核实履行事实承担相应责任。','部分支持许某的请求，具体金额以判决主文为准。','部分支持','租赁,供暖结算,书面证据,缴费凭证和合同附件对结算周期记载不同');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_a6f4f85837','（2024）京民初2591号','韩某与瑞景物业管理有限公司钥匙交接纠纷','court_cp','合同纠纷','钥匙交接','2024-09-20','韩某、瑞景物业管理有限公司','案件发生在租赁履行期间。交房时钥匙数量与退租清单不一致；与钥匙交接相关的材料包括双方签字的交接单只列明三把钥匙。','交房时钥匙数量与退租清单不一致。庭审材料显示，双方签字的交接单只列明三把钥匙。双方对合同相关条款的解释不一致。','法院围绕钥匙交接核对承诺形成时间及书面记录，现有材料显示，双方签字的交接单只列明三把钥匙。','经调解，双方就钥匙交接的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,钥匙交接,书面证据,双方签字的交接单只列明三把钥匙');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_59a0d7f221','（2024）京民初2628号','杜某与海淀住房租赁管理有限公司押金返还纠纷','court_sjs','合同纠纷','押金返还','2024-10-13','杜某、海淀住房租赁管理有限公司','杜某与海淀住房租赁管理有限公司对押金返还协商未果。已查明退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围，并有租客提交入住照片、退租视频和保洁票据佐证。','退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围。庭审材料显示，租客提交入住照片、退租视频和保洁票据。双方对合同相关条款的解释不一致。','主张押金返还的一方需说明计算方式和合同依据；现有证据中，租客提交入住照片、退租视频和保洁票据。','对有书面凭证支持的押金返还主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,押金返还,书面证据,租客提交入住照片、退租视频和保洁票据');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_d5cca71a12','（2024）京民初2665号','顾某与清河物业服务中心噪声影响纠纷','court_hd','合同纠纷','噪声影响','2024-11-05','顾某、清河物业服务中心','法院审理的核心是噪声影响。出租前未披露相邻施工，租客入住后主张影响正常居住，现有书面材料中包含施工公告和看房时间能够证明披露范围。','出租前未披露相邻施工，租客入住后主张影响正常居住。庭审材料显示，施工公告和看房时间能够证明披露范围。双方对合同相关条款的解释不一致。','判断噪声影响是否影响合同履行，需要比较看房时披露内容、公告时间和实际通行情况。施工公告和看房时间能够证明披露范围。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,噪声影响,书面证据,施工公告和看房时间能够证明披露范围');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_4b1c604ee1','（2024）京民初2702号','叶某与诚家房地产经纪中心租金调整纠纷','court_xc','合同纠纷','租金调整','2024-11-28','叶某、诚家房地产经纪中心','双方合同履行过程中出现租金调整争议。续租报价在短期内多次变化，租客主张应按较早报价履行；证据链以邮件中未出现明确接受或签署记录为主。','续租报价在短期内多次变化，租客主张应按较早报价履行。庭审材料显示，邮件中未出现明确接受或签署记录。双方对合同相关条款的解释不一致。','法院围绕租金调整审查书面条款、沟通时间和资金流，注意到邮件中未出现明确接受或签署记录。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,租金调整,书面证据,邮件中未出现明确接受或签署记录');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_12da7ad2d5','（2024）京民终2739号','唐某与上地公寓运营中心搬家通道纠纷','court_bj2','其他','搬家通道','2024-12-21','唐某、上地公寓运营中心','该案涉及搬家通道及相应费用承担。物业临时封闭车库通道，租客增加搬运费用，提交的关键材料为公告发布时间晚于搬家公司预约时间。','物业临时封闭车库通道，租客增加搬运费用。庭审材料显示，公告发布时间晚于搬家公司预约时间。双方对合同相关条款的解释不一致。','搬家通道的责任范围取决于变化是否可预见以及是否造成实际损失；公告发布时间晚于搬家公司预约时间。','双方应按合同及已核实履行事实承担相应责任。','部分支持唐某的请求，具体金额以判决主文为准。','部分支持','租赁,搬家通道,书面证据,公告发布时间晚于搬家公司预约时间');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_a5deca4b78','（2025）京民初2776号','张某与安居住房服务有限公司出租权限纠纷','court_cy','合同纠纷','出租权限','2025-01-13','张某、安居住房服务有限公司','张某与安居住房服务有限公司因出租权限发生争议。签约人并非产权登记人，双方争议其是否取得有效委托。主要证据为委托书、产权材料和收款账户是争议焦点。','签约人并非产权登记人，双方争议其是否取得有效委托。庭审材料显示，委托书、产权材料和收款账户是争议焦点。双方对合同相关条款的解释不一致。','出租权限取决于授权范围、材料来源和接收主体是否清楚。委托书、产权材料和收款账户是争议焦点。','经调解，双方就出租权限的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,出租权限,书面证据,委托书、产权材料和收款账户是争议焦点');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_c4ee06027c','（2025）京民初2813号','李某与明远资产管理有限公司个人信息纠纷','court_ft','侵权责任','个人信息','2025-02-05','李某、明远资产管理有限公司','本案处理个人信息问题：经纪人要求提前发送身份证和收入证明，租客质疑收集范围；庭审中提交了机构未能说明资料保存期限和接收人员。','经纪人要求提前发送身份证和收入证明，租客质疑收集范围。庭审材料显示，机构未能说明资料保存期限和接收人员。双方对合同相关条款的解释不一致。','法院核对主体身份、授权文件和资料用途后处理个人信息；机构未能说明资料保存期限和接收人员。','对有书面凭证支持的个人信息主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,个人信息,书面证据,机构未能说明资料保存期限和接收人员');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_d3ad36972e','（2025）京仲2850号','王某与京北房屋经纪有限公司电器折旧纠纷','court_bjac','合同纠纷','电器折旧','2025-02-28','王某、京北房屋经纪有限公司','京北房屋经纪有限公司与王某对电器折旧的责任范围意见不一。查明事实为空调压缩机故障后出租方要求租客承担全部更换费，证据包括检测报告认为设备已接近设计寿命。','空调压缩机故障后出租方要求租客承担全部更换费。庭审材料显示，检测报告认为设备已接近设计寿命。双方对合同相关条款的解释不一致。','关于电器折旧，工单、检测报告和现场照片比单方陈述更能还原经过；检测报告认为设备已接近设计寿命。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,电器折旧,书面证据,检测报告认为设备已接近设计寿命');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_faf829c665','（2025）京民初2887号','赵某与瑞景物业管理有限公司维修垫付纠纷','court_xc','合同纠纷','维修垫付','2025-03-23','赵某、瑞景物业管理有限公司','争议源于热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议。赵某据此主张处理维修垫付，并提交报修工单显示故障发生后当天通知房东。','热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议。庭审材料显示，报修工单显示故障发生后当天通知房东。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断维修垫付责任。报修工单显示故障发生后当天通知房东。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,维修垫付,书面证据,报修工单显示故障发生后当天通知房东');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_2d3be76c23','（2025）京民终2924号','陈某与海淀住房租赁管理有限公司门禁变更纠纷','court_bj2','其他','门禁变更','2025-04-15','陈某、海淀住房租赁管理有限公司','围绕门禁变更，双方确认租赁关系存在，但对费用和责任有分歧。小区夜间关闭部分入口，租客认为通勤条件明显变化；物业公告说明入口调整属于阶段性管理措施。','小区夜间关闭部分入口，租客认为通勤条件明显变化。庭审材料显示，物业公告说明入口调整属于阶段性管理措施。双方对合同相关条款的解释不一致。','法院结合物业公告、现场路线和新增费用审查门禁变更，其中物业公告说明入口调整属于阶段性管理措施。','双方应按合同及已核实履行事实承担相应责任。','部分支持陈某的请求，具体金额以判决主文为准。','部分支持','租赁,门禁变更,书面证据,物业公告说明入口调整属于阶段性管理措施');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_c59a2b8919','（2025）京民初2961号','周某与清河物业服务中心付款账户纠纷','court_cy','合同纠纷','付款账户','2025-05-08','周某、清河物业服务中心','周某起诉要求解决付款账户。案件材料记载出租方临时要求改向个人账户付款，租客拒绝后产生争议，其中原合同和历史流水均指向另一账户。','出租方临时要求改向个人账户付款，租客拒绝后产生争议。庭审材料显示，原合同和历史流水均指向另一账户。双方对合同相关条款的解释不一致。','主张付款账户的一方需说明计算方式和合同依据；现有证据中，原合同和历史流水均指向另一账户。','经调解，双方就付款账户的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,付款账户,书面证据,原合同和历史流水均指向另一账户');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_fcc86180a6','（2025）京民初2998号','孙某与诚家房地产经纪中心租期衔接纠纷','court_ft','合同纠纷','租期衔接','2025-05-31','孙某、诚家房地产经纪中心','租期衔接是本案主要争点。新租约起始日与旧租约终止日重叠，双方分别就双方对钥匙和租金按日结算未达成一致发表意见。','新租约起始日与旧租约终止日重叠。庭审材料显示，双方对钥匙和租金按日结算未达成一致。双方对合同相关条款的解释不一致。','租期衔接应先看合同约定，再核对实际付款、退款条件和金额凭证。双方对钥匙和租金按日结算未达成一致。','对有书面凭证支持的租期衔接主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,租期衔接,书面证据,双方对钥匙和租金按日结算未达成一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_7230835108','（2025）京仲3035号','刘某与上地公寓运营中心家具损坏纠纷','court_bjac','合同纠纷','家具损坏','2025-06-23','刘某、上地公寓运营中心','案件发生在租赁履行期间。退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用；与家具损坏相关的材料包括交接照片显示铰链此前已有松动。','退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。庭审材料显示，交接照片显示铰链此前已有松动。双方对合同相关条款的解释不一致。','处理家具损坏需要区分自然损耗、公共部位责任和不当使用。现有材料显示，交接照片显示铰链此前已有松动。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,家具损坏,书面证据,交接照片显示铰链此前已有松动');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_694b8288f2','（2025）京民初3072号','高某与安居住房服务有限公司物业维修纠纷','court_cp','其他','物业维修','2025-07-16','高某、安居住房服务有限公司','高某与安居住房服务有限公司对物业维修协商未果。已查明公共排水堵塞造成室内返水，物业与出租方争议责任分担，并有维修记录显示堵点位于公共立管佐证。','公共排水堵塞造成室内返水，物业与出租方争议责任分担。庭审材料显示，维修记录显示堵点位于公共立管。双方对合同相关条款的解释不一致。','关于物业维修，工单、检测报告和现场照片比单方陈述更能还原经过；维修记录显示堵点位于公共立管。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,物业维修,书面证据,维修记录显示堵点位于公共立管');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_e8b295a8db','（2025）京民初3109号','林某与明远资产管理有限公司转租授权纠纷','court_sjs','合同纠纷','转租授权','2025-08-08','林某、明远资产管理有限公司','法院审理的核心是转租授权。二房东签约后无法提供原出租人的转租同意，现有书面材料中包含主合同中存在禁止转租条款。','二房东签约后无法提供原出租人的转租同意。庭审材料显示，主合同中存在禁止转租条款。双方对合同相关条款的解释不一致。','转租授权取决于授权范围、材料来源和接收主体是否清楚。主合同中存在禁止转租条款。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,转租授权,书面证据,主合同中存在禁止转租条款');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_265431ede7','（2025）京民初3146号','许某与京北房屋经纪有限公司经纪服务费纠纷','court_hd','合同纠纷','经纪服务费','2025-08-31','许某、京北房屋经纪有限公司','双方合同履行过程中出现经纪服务费争议。经纪人在签约前后对服务费口径表述不一致；证据链以平台页面和聊天记录显示收费项目发生变化为主。','经纪人在签约前后对服务费口径表述不一致。庭审材料显示，平台页面和聊天记录显示收费项目发生变化。双方对合同相关条款的解释不一致。','法院围绕经纪服务费审查书面条款、沟通时间和资金流，注意到平台页面和聊天记录显示收费项目发生变化。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,经纪服务费,书面证据,平台页面和聊天记录显示收费项目发生变化');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_4c60965a93','（2025）京民初3183号','韩某与瑞景物业管理有限公司定金性质纠纷','court_xc','合同纠纷','定金性质','2025-09-23','韩某、瑞景物业管理有限公司','该案涉及定金性质及相应费用承担。付款备注写作意向金，收据写作定金，双方争议退款条件，提交的关键材料为付款前后文本对款项用途表述不一致。','付款备注写作意向金，收据写作定金，双方争议退款条件。庭审材料显示，付款前后文本对款项用途表述不一致。双方对合同相关条款的解释不一致。','主张定金性质的一方需说明计算方式和合同依据；现有证据中，付款前后文本对款项用途表述不一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持韩某的请求，具体金额以判决主文为准。','部分支持','租赁,定金性质,书面证据,付款前后文本对款项用途表述不一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_e35a06c131','（2025）京民终3220号','杜某与海淀住房租赁管理有限公司清洁费用纠纷','court_bj2','合同纠纷','清洁费用','2025-10-16','杜某、海淀住房租赁管理有限公司','杜某与海淀住房租赁管理有限公司因清洁费用发生争议。合同只写恢复整洁，退租时出租方主张高额深度清洁费。主要证据为出租方未提供实际清洁发票。','合同只写恢复整洁，退租时出租方主张高额深度清洁费。庭审材料显示，出租方未提供实际清洁发票。双方对合同相关条款的解释不一致。','清洁费用应先看合同约定，再核对实际付款、退款条件和金额凭证。出租方未提供实际清洁发票。','经调解，双方就清洁费用的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,清洁费用,书面证据,出租方未提供实际清洁发票');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_72dc583bb9','（2025）京民初3257号','顾某与清河物业服务中心押金返还纠纷','court_cy','合同纠纷','押金返还','2025-11-08','顾某、清河物业服务中心','本案处理押金返还问题：退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围；庭审中提交了租客提交入住照片、退租视频和保洁票据。','退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围。庭审材料显示，租客提交入住照片、退租视频和保洁票据。双方对合同相关条款的解释不一致。','法院围绕押金返还审查书面条款、沟通时间和资金流，注意到租客提交入住照片、退租视频和保洁票据。','对有书面凭证支持的押金返还主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,押金返还,书面证据,租客提交入住照片、退租视频和保洁票据');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b214cea754','（2025）京民初3294号','叶某与诚家房地产经纪中心噪声影响纠纷','court_ft','合同纠纷','噪声影响','2025-12-01','叶某、诚家房地产经纪中心','诚家房地产经纪中心与叶某对噪声影响的责任范围意见不一。查明事实为出租前未披露相邻施工，租客入住后主张影响正常居住，证据包括施工公告和看房时间能够证明披露范围。','出租前未披露相邻施工，租客入住后主张影响正常居住。庭审材料显示，施工公告和看房时间能够证明披露范围。双方对合同相关条款的解释不一致。','噪声影响的责任范围取决于变化是否可预见以及是否造成实际损失；施工公告和看房时间能够证明披露范围。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,噪声影响,书面证据,施工公告和看房时间能够证明披露范围');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b6ac385fd4','（2025）京仲3331号','唐某与上地公寓运营中心租金调整纠纷','court_bjac','合同纠纷','租金调整','2025-12-24','唐某、上地公寓运营中心','争议源于续租报价在短期内多次变化，租客主张应按较早报价履行。唐某据此主张处理租金调整，并提交邮件中未出现明确接受或签署记录。','续租报价在短期内多次变化，租客主张应按较早报价履行。庭审材料显示，邮件中未出现明确接受或签署记录。双方对合同相关条款的解释不一致。','租金调整应先看合同约定，再核对实际付款、退款条件和金额凭证。邮件中未出现明确接受或签署记录。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,租金调整,书面证据,邮件中未出现明确接受或签署记录');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_066a79c64b','（2026）京民初3368号','张某与安居住房服务有限公司搬家通道纠纷','court_cp','其他','搬家通道','2026-01-16','张某、安居住房服务有限公司','围绕搬家通道，双方确认租赁关系存在，但对费用和责任有分歧。物业临时封闭车库通道，租客增加搬运费用；公告发布时间晚于搬家公司预约时间。','物业临时封闭车库通道，租客增加搬运费用。庭审材料显示，公告发布时间晚于搬家公司预约时间。双方对合同相关条款的解释不一致。','法院结合物业公告、现场路线和新增费用审查搬家通道，其中公告发布时间晚于搬家公司预约时间。','双方应按合同及已核实履行事实承担相应责任。','部分支持张某的请求，具体金额以判决主文为准。','部分支持','租赁,搬家通道,书面证据,公告发布时间晚于搬家公司预约时间');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_6b21a4d507','（2026）京民初3405号','李某与明远资产管理有限公司出租权限纠纷','court_sjs','合同纠纷','出租权限','2026-02-08','李某、明远资产管理有限公司','李某起诉要求解决出租权限。案件材料记载签约人并非产权登记人，双方争议其是否取得有效委托，其中委托书、产权材料和收款账户是争议焦点。','签约人并非产权登记人，双方争议其是否取得有效委托。庭审材料显示，委托书、产权材料和收款账户是争议焦点。双方对合同相关条款的解释不一致。','对于出租权限，不能只凭口头说明，应结合可追溯的书面材料。现有材料表明，委托书、产权材料和收款账户是争议焦点。','经调解，双方就出租权限的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,出租权限,书面证据,委托书、产权材料和收款账户是争议焦点');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_05ec077794','（2026）京民初3442号','王某与京北房屋经纪有限公司租赁登记纠纷','court_hd','合同纠纷','租赁登记','2026-03-03','王某、京北房屋经纪有限公司','租赁登记是本案主要争点。合同未约定由谁准备登记材料，入住后双方相互推诿，双方分别就社区窗口清单能够说明所需材料发表意见。','合同未约定由谁准备登记材料，入住后双方相互推诿。庭审材料显示，社区窗口清单能够说明所需材料。双方对合同相关条款的解释不一致。','租赁登记取决于授权范围、材料来源和接收主体是否清楚。社区窗口清单能够说明所需材料。','对有书面凭证支持的租赁登记主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,租赁登记,书面证据,社区窗口清单能够说明所需材料');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_0e76b31392','（2026）京民初3479号','赵某与瑞景物业管理有限公司看房承诺纠纷','court_xc','合同纠纷','看房承诺','2026-03-26','赵某、瑞景物业管理有限公司','案件发生在租赁履行期间。经纪人口头承诺可养宠物，合同草案却明确禁止；与看房承诺相关的材料包括录音、平台详情和草案内容彼此冲突。','经纪人口头承诺可养宠物，合同草案却明确禁止。庭审材料显示，录音、平台详情和草案内容彼此冲突。双方对合同相关条款的解释不一致。','法院围绕看房承诺核对承诺形成时间及书面记录，现有材料显示，录音、平台详情和草案内容彼此冲突。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,看房承诺,书面证据,录音、平台详情和草案内容彼此冲突');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_9bb9a6319b','（2026）京仲3516号','陈某与海淀住房租赁管理有限公司外墙渗水纠纷','court_bjac','合同纠纷','外墙渗水','2026-04-18','陈某、海淀住房租赁管理有限公司','陈某与海淀住房租赁管理有限公司对外墙渗水协商未果。已查明暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关，并有物业工单、气象记录和墙面照片能够相互印证佐证。','暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关。庭审材料显示，物业工单、气象记录和墙面照片能够相互印证。双方对合同相关条款的解释不一致。','关于外墙渗水，工单、检测报告和现场照片比单方陈述更能还原经过；物业工单、气象记录和墙面照片能够相互印证。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,外墙渗水,书面证据,物业工单、气象记录和墙面照片能够相互印证');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_6beb3b13bc','（2026）京民初3553号','周某与清河物业服务中心供暖结算纠纷','court_cp','合同纠纷','供暖结算','2026-05-11','周某、清河物业服务中心','法院审理的核心是供暖结算。租期跨越供暖季，预收供暖费的退还方式没有写清，现有书面材料中包含缴费凭证和合同附件对结算周期记载不同。','租期跨越供暖季，预收供暖费的退还方式没有写清。庭审材料显示，缴费凭证和合同附件对结算周期记载不同。双方对合同相关条款的解释不一致。','供暖结算应先看合同约定，再核对实际付款、退款条件和金额凭证。缴费凭证和合同附件对结算周期记载不同。','双方应按合同及已核实履行事实承担相应责任。','部分支持周某的请求，具体金额以判决主文为准。','部分支持','租赁,供暖结算,书面证据,缴费凭证和合同附件对结算周期记载不同');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b0190dccd2','（2022）京民初3590号','孙某与诚家房地产经纪中心钥匙交接纠纷','court_sjs','合同纠纷','钥匙交接','2022-01-05','孙某、诚家房地产经纪中心','双方合同履行过程中出现钥匙交接争议。交房时钥匙数量与退租清单不一致；证据链以双方签字的交接单只列明三把钥匙为主。','交房时钥匙数量与退租清单不一致。庭审材料显示，双方签字的交接单只列明三把钥匙。双方对合同相关条款的解释不一致。','法院围绕钥匙交接核对承诺形成时间及书面记录，现有材料显示，双方签字的交接单只列明三把钥匙。','经调解，双方就钥匙交接的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,钥匙交接,书面证据,双方签字的交接单只列明三把钥匙');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_61a19115dc','（2022）京民初3627号','刘某与上地公寓运营中心发票开具纠纷','court_hd','合同纠纷','发票开具','2022-01-28','刘某、上地公寓运营中心','该案涉及发票开具及相应费用承担。机构收取服务费后长期未开具发票，提交的关键材料为付款记录和多次催办邮件可以核实。','机构收取服务费后长期未开具发票。庭审材料显示，付款记录和多次催办邮件可以核实。双方对合同相关条款的解释不一致。','主张发票开具的一方需说明计算方式和合同依据；现有证据中，付款记录和多次催办邮件可以核实。','对有书面凭证支持的发票开具主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,发票开具,书面证据,付款记录和多次催办邮件可以核实');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_04ed591dca','（2022）京民初3664号','高某与安居住房服务有限公司家具损坏纠纷','court_xc','合同纠纷','家具损坏','2022-02-20','高某、安居住房服务有限公司','高某与安居住房服务有限公司因家具损坏发生争议。退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。主要证据为交接照片显示铰链此前已有松动。','退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。庭审材料显示，交接照片显示铰链此前已有松动。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断家具损坏责任。交接照片显示铰链此前已有松动。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,家具损坏,书面证据,交接照片显示铰链此前已有松动');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_0e15c05fd4','（2022）京民终3701号','林某与明远资产管理有限公司物业维修纠纷','court_bj2','其他','物业维修','2022-03-15','林某、明远资产管理有限公司','本案处理物业维修问题：公共排水堵塞造成室内返水，物业与出租方争议责任分担；庭审中提交了维修记录显示堵点位于公共立管。','公共排水堵塞造成室内返水，物业与出租方争议责任分担。庭审材料显示，维修记录显示堵点位于公共立管。双方对合同相关条款的解释不一致。','处理物业维修需要区分自然损耗、公共部位责任和不当使用。现有材料显示，维修记录显示堵点位于公共立管。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,物业维修,书面证据,维修记录显示堵点位于公共立管');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_23f486daf8','（2022）京民初3738号','许某与京北房屋经纪有限公司转租授权纠纷','court_cy','合同纠纷','转租授权','2022-04-07','许某、京北房屋经纪有限公司','京北房屋经纪有限公司与许某对转租授权的责任范围意见不一。查明事实为二房东签约后无法提供原出租人的转租同意，证据包括主合同中存在禁止转租条款。','二房东签约后无法提供原出租人的转租同意。庭审材料显示，主合同中存在禁止转租条款。双方对合同相关条款的解释不一致。','对于转租授权，不能只凭口头说明，应结合可追溯的书面材料。现有材料表明，主合同中存在禁止转租条款。','双方应按合同及已核实履行事实承担相应责任。','部分支持许某的请求，具体金额以判决主文为准。','部分支持','租赁,转租授权,书面证据,主合同中存在禁止转租条款');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_24cd45a753','（2022）京民初3775号','韩某与瑞景物业管理有限公司经纪服务费纠纷','court_ft','合同纠纷','经纪服务费','2022-04-30','韩某、瑞景物业管理有限公司','争议源于经纪人在签约前后对服务费口径表述不一致。韩某据此主张处理经纪服务费，并提交平台页面和聊天记录显示收费项目发生变化。','经纪人在签约前后对服务费口径表述不一致。庭审材料显示，平台页面和聊天记录显示收费项目发生变化。双方对合同相关条款的解释不一致。','经纪服务费应先看合同约定，再核对实际付款、退款条件和金额凭证。平台页面和聊天记录显示收费项目发生变化。','经调解，双方就经纪服务费的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,经纪服务费,书面证据,平台页面和聊天记录显示收费项目发生变化');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_d27d35bf29','（2022）京仲3812号','杜某与海淀住房租赁管理有限公司定金性质纠纷','court_bjac','合同纠纷','定金性质','2022-05-23','杜某、海淀住房租赁管理有限公司','围绕定金性质，双方确认租赁关系存在，但对费用和责任有分歧。付款备注写作意向金，收据写作定金，双方争议退款条件；付款前后文本对款项用途表述不一致。','付款备注写作意向金，收据写作定金，双方争议退款条件。庭审材料显示，付款前后文本对款项用途表述不一致。双方对合同相关条款的解释不一致。','法院围绕定金性质审查书面条款、沟通时间和资金流，注意到付款前后文本对款项用途表述不一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持杜某的请求，具体金额以判决主文为准。','部分支持','租赁,定金性质,书面证据,付款前后文本对款项用途表述不一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_38cb3fa41c','（2022）京民初3849号','顾某与清河物业服务中心电器折旧纠纷','court_cp','合同纠纷','电器折旧','2022-06-15','顾某、清河物业服务中心','顾某起诉要求解决电器折旧。案件材料记载空调压缩机故障后出租方要求租客承担全部更换费，其中检测报告认为设备已接近设计寿命。','空调压缩机故障后出租方要求租客承担全部更换费。庭审材料显示，检测报告认为设备已接近设计寿命。双方对合同相关条款的解释不一致。','关于电器折旧，工单、检测报告和现场照片比单方陈述更能还原经过；检测报告认为设备已接近设计寿命。','经调解，双方就电器折旧的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,电器折旧,书面证据,检测报告认为设备已接近设计寿命');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_914f4efe1c','（2022）京民初3886号','叶某与诚家房地产经纪中心维修垫付纠纷','court_sjs','合同纠纷','维修垫付','2022-07-08','叶某、诚家房地产经纪中心','维修垫付是本案主要争点。热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议，双方分别就报修工单显示故障发生后当天通知房东发表意见。','热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议。庭审材料显示，报修工单显示故障发生后当天通知房东。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断维修垫付责任。报修工单显示故障发生后当天通知房东。','对有书面凭证支持的维修垫付主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,维修垫付,书面证据,报修工单显示故障发生后当天通知房东');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_67e4c05452','（2022）京民初3923号','唐某与上地公寓运营中心门禁变更纠纷','court_hd','其他','门禁变更','2022-07-31','唐某、上地公寓运营中心','案件发生在租赁履行期间。小区夜间关闭部分入口，租客认为通勤条件明显变化；与门禁变更相关的材料包括物业公告说明入口调整属于阶段性管理措施。','小区夜间关闭部分入口，租客认为通勤条件明显变化。庭审材料显示，物业公告说明入口调整属于阶段性管理措施。双方对合同相关条款的解释不一致。','法院结合物业公告、现场路线和新增费用审查门禁变更，其中物业公告说明入口调整属于阶段性管理措施。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,门禁变更,书面证据,物业公告说明入口调整属于阶段性管理措施');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_683e7bccf2','（2022）京民初3960号','张某与安居住房服务有限公司付款账户纠纷','court_xc','合同纠纷','付款账户','2022-08-23','张某、安居住房服务有限公司','张某与安居住房服务有限公司对付款账户协商未果。已查明出租方临时要求改向个人账户付款，租客拒绝后产生争议，并有原合同和历史流水均指向另一账户佐证。','出租方临时要求改向个人账户付款，租客拒绝后产生争议。庭审材料显示，原合同和历史流水均指向另一账户。双方对合同相关条款的解释不一致。','主张付款账户的一方需说明计算方式和合同依据；现有证据中，原合同和历史流水均指向另一账户。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,付款账户,书面证据,原合同和历史流水均指向另一账户');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_e5bf898a56','（2022）京民终3997号','李某与明远资产管理有限公司租期衔接纠纷','court_bj2','合同纠纷','租期衔接','2022-09-15','李某、明远资产管理有限公司','法院审理的核心是租期衔接。新租约起始日与旧租约终止日重叠，现有书面材料中包含双方对钥匙和租金按日结算未达成一致。','新租约起始日与旧租约终止日重叠。庭审材料显示，双方对钥匙和租金按日结算未达成一致。双方对合同相关条款的解释不一致。','租期衔接应先看合同约定，再核对实际付款、退款条件和金额凭证。双方对钥匙和租金按日结算未达成一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持李某的请求，具体金额以判决主文为准。','部分支持','租赁,租期衔接,书面证据,双方对钥匙和租金按日结算未达成一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_4ea5634e72','（2022）京民初4034号','王某与京北房屋经纪有限公司提前解约纠纷','court_cy','合同纠纷','提前解约','2022-10-08','王某、京北房屋经纪有限公司','双方合同履行过程中出现提前解约争议。租客因工作地点变化提前退租，合同约定与补充协议表述不一致；证据链以双方邮件对解约通知期有不同理解为主。','租客因工作地点变化提前退租，合同约定与补充协议表述不一致。庭审材料显示，双方邮件对解约通知期有不同理解。双方对合同相关条款的解释不一致。','法院围绕提前解约审查书面条款、沟通时间和资金流，注意到双方邮件对解约通知期有不同理解。','经调解，双方就提前解约的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,提前解约,书面证据,双方邮件对解约通知期有不同理解');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_4d3bc5ec6b','（2022）京民初4071号','赵某与瑞景物业管理有限公司租赁登记纠纷','court_ft','合同纠纷','租赁登记','2022-10-31','赵某、瑞景物业管理有限公司','该案涉及租赁登记及相应费用承担。合同未约定由谁准备登记材料，入住后双方相互推诿，提交的关键材料为社区窗口清单能够说明所需材料。','合同未约定由谁准备登记材料，入住后双方相互推诿。庭审材料显示，社区窗口清单能够说明所需材料。双方对合同相关条款的解释不一致。','对于租赁登记，不能只凭口头说明，应结合可追溯的书面材料。现有材料表明，社区窗口清单能够说明所需材料。','对有书面凭证支持的租赁登记主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,租赁登记,书面证据,社区窗口清单能够说明所需材料');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_ff409cf755','（2022）京仲4108号','陈某与海淀住房租赁管理有限公司看房承诺纠纷','court_bjac','合同纠纷','看房承诺','2022-11-23','陈某、海淀住房租赁管理有限公司','陈某与海淀住房租赁管理有限公司因看房承诺发生争议。经纪人口头承诺可养宠物，合同草案却明确禁止。主要证据为录音、平台详情和草案内容彼此冲突。','经纪人口头承诺可养宠物，合同草案却明确禁止。庭审材料显示，录音、平台详情和草案内容彼此冲突。双方对合同相关条款的解释不一致。','处理看房承诺应比较合同草案、交接记录和双方沟通。录音、平台详情和草案内容彼此冲突。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,看房承诺,书面证据,录音、平台详情和草案内容彼此冲突');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_4f03f9c9a4','（2022）京民初4145号','周某与清河物业服务中心外墙渗水纠纷','court_xc','合同纠纷','外墙渗水','2022-12-16','周某、清河物业服务中心','本案处理外墙渗水问题：暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关；庭审中提交了物业工单、气象记录和墙面照片能够相互印证。','暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关。庭审材料显示，物业工单、气象记录和墙面照片能够相互印证。双方对合同相关条款的解释不一致。','处理外墙渗水需要区分自然损耗、公共部位责任和不当使用。现有材料显示，物业工单、气象记录和墙面照片能够相互印证。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,外墙渗水,书面证据,物业工单、气象记录和墙面照片能够相互印证');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_73cd592496','（2023）京民终4182号','孙某与诚家房地产经纪中心供暖结算纠纷','court_bj2','合同纠纷','供暖结算','2023-01-08','孙某、诚家房地产经纪中心','诚家房地产经纪中心与孙某对供暖结算的责任范围意见不一。查明事实为租期跨越供暖季，预收供暖费的退还方式没有写清，证据包括缴费凭证和合同附件对结算周期记载不同。','租期跨越供暖季，预收供暖费的退还方式没有写清。庭审材料显示，缴费凭证和合同附件对结算周期记载不同。双方对合同相关条款的解释不一致。','主张供暖结算的一方需说明计算方式和合同依据；现有证据中，缴费凭证和合同附件对结算周期记载不同。','双方应按合同及已核实履行事实承担相应责任。','部分支持孙某的请求，具体金额以判决主文为准。','部分支持','租赁,供暖结算,书面证据,缴费凭证和合同附件对结算周期记载不同');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_7e361d30ac','（2023）京民初4219号','刘某与上地公寓运营中心钥匙交接纠纷','court_cy','合同纠纷','钥匙交接','2023-01-31','刘某、上地公寓运营中心','争议源于交房时钥匙数量与退租清单不一致。刘某据此主张处理钥匙交接，并提交双方签字的交接单只列明三把钥匙。','交房时钥匙数量与退租清单不一致。庭审材料显示，双方签字的交接单只列明三把钥匙。双方对合同相关条款的解释不一致。','处理钥匙交接应比较合同草案、交接记录和双方沟通。双方签字的交接单只列明三把钥匙。','经调解，双方就钥匙交接的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,钥匙交接,书面证据,双方签字的交接单只列明三把钥匙');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_05f2195eee','（2023）京民初4256号','高某与安居住房服务有限公司押金返还纠纷','court_ft','合同纠纷','押金返还','2023-02-23','高某、安居住房服务有限公司','围绕押金返还，双方确认租赁关系存在，但对费用和责任有分歧。退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围；租客提交入住照片、退租视频和保洁票据。','退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围。庭审材料显示，租客提交入住照片、退租视频和保洁票据。双方对合同相关条款的解释不一致。','法院围绕押金返还审查书面条款、沟通时间和资金流，注意到租客提交入住照片、退租视频和保洁票据。','对有书面凭证支持的押金返还主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,押金返还,书面证据,租客提交入住照片、退租视频和保洁票据');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_455191af96','（2023）京仲4293号','林某与明远资产管理有限公司噪声影响纠纷','court_bjac','合同纠纷','噪声影响','2023-03-18','林某、明远资产管理有限公司','林某起诉要求解决噪声影响。案件材料记载出租前未披露相邻施工，租客入住后主张影响正常居住，其中施工公告和看房时间能够证明披露范围。','出租前未披露相邻施工，租客入住后主张影响正常居住。庭审材料显示，施工公告和看房时间能够证明披露范围。双方对合同相关条款的解释不一致。','噪声影响的责任范围取决于变化是否可预见以及是否造成实际损失；施工公告和看房时间能够证明披露范围。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,噪声影响,书面证据,施工公告和看房时间能够证明披露范围');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_c7d62df77e','（2023）京民初4330号','许某与京北房屋经纪有限公司租金调整纠纷','court_cp','合同纠纷','租金调整','2023-04-10','许某、京北房屋经纪有限公司','租金调整是本案主要争点。续租报价在短期内多次变化，租客主张应按较早报价履行，双方分别就邮件中未出现明确接受或签署记录发表意见。','续租报价在短期内多次变化，租客主张应按较早报价履行。庭审材料显示，邮件中未出现明确接受或签署记录。双方对合同相关条款的解释不一致。','租金调整应先看合同约定，再核对实际付款、退款条件和金额凭证。邮件中未出现明确接受或签署记录。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,租金调整,书面证据,邮件中未出现明确接受或签署记录');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_4a6399fe69','（2023）京民初4367号','韩某与瑞景物业管理有限公司搬家通道纠纷','court_sjs','其他','搬家通道','2023-05-03','韩某、瑞景物业管理有限公司','案件发生在租赁履行期间。物业临时封闭车库通道，租客增加搬运费用；与搬家通道相关的材料包括公告发布时间晚于搬家公司预约时间。','物业临时封闭车库通道，租客增加搬运费用。庭审材料显示，公告发布时间晚于搬家公司预约时间。双方对合同相关条款的解释不一致。','法院结合物业公告、现场路线和新增费用审查搬家通道，其中公告发布时间晚于搬家公司预约时间。','双方应按合同及已核实履行事实承担相应责任。','部分支持韩某的请求，具体金额以判决主文为准。','部分支持','租赁,搬家通道,书面证据,公告发布时间晚于搬家公司预约时间');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b4f0d1b978','（2023）京民初4404号','杜某与海淀住房租赁管理有限公司出租权限纠纷','court_hd','合同纠纷','出租权限','2023-05-26','杜某、海淀住房租赁管理有限公司','杜某与海淀住房租赁管理有限公司对出租权限协商未果。已查明签约人并非产权登记人，双方争议其是否取得有效委托，并有委托书、产权材料和收款账户是争议焦点佐证。','签约人并非产权登记人，双方争议其是否取得有效委托。庭审材料显示，委托书、产权材料和收款账户是争议焦点。双方对合同相关条款的解释不一致。','对于出租权限，不能只凭口头说明，应结合可追溯的书面材料。现有材料表明，委托书、产权材料和收款账户是争议焦点。','经调解，双方就出租权限的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,出租权限,书面证据,委托书、产权材料和收款账户是争议焦点');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_8a1cab6b0c','（2023）京民初4441号','顾某与清河物业服务中心个人信息纠纷','court_xc','侵权责任','个人信息','2023-06-18','顾某、清河物业服务中心','法院审理的核心是个人信息。经纪人要求提前发送身份证和收入证明，租客质疑收集范围，现有书面材料中包含机构未能说明资料保存期限和接收人员。','经纪人要求提前发送身份证和收入证明，租客质疑收集范围。庭审材料显示，机构未能说明资料保存期限和接收人员。双方对合同相关条款的解释不一致。','个人信息取决于授权范围、材料来源和接收主体是否清楚。机构未能说明资料保存期限和接收人员。','对有书面凭证支持的个人信息主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,个人信息,书面证据,机构未能说明资料保存期限和接收人员');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_1b4ac11ac3','（2023）京民终4478号','叶某与诚家房地产经纪中心电器折旧纠纷','court_bj2','合同纠纷','电器折旧','2023-07-11','叶某、诚家房地产经纪中心','双方合同履行过程中出现电器折旧争议。空调压缩机故障后出租方要求租客承担全部更换费；证据链以检测报告认为设备已接近设计寿命为主。','空调压缩机故障后出租方要求租客承担全部更换费。庭审材料显示，检测报告认为设备已接近设计寿命。双方对合同相关条款的解释不一致。','处理电器折旧需要区分自然损耗、公共部位责任和不当使用。现有材料显示，检测报告认为设备已接近设计寿命。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,电器折旧,书面证据,检测报告认为设备已接近设计寿命');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_25673dc1de','（2023）京民初4515号','唐某与上地公寓运营中心维修垫付纠纷','court_cy','合同纠纷','维修垫付','2023-08-03','唐某、上地公寓运营中心','该案涉及维修垫付及相应费用承担。热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议，提交的关键材料为报修工单显示故障发生后当天通知房东。','热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议。庭审材料显示，报修工单显示故障发生后当天通知房东。双方对合同相关条款的解释不一致。','关于维修垫付，工单、检测报告和现场照片比单方陈述更能还原经过；报修工单显示故障发生后当天通知房东。','对有书面凭证支持的维修垫付主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,维修垫付,书面证据,报修工单显示故障发生后当天通知房东');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_30ed76757d','（2023）京民初4552号','张某与安居住房服务有限公司门禁变更纠纷','court_ft','其他','门禁变更','2023-08-26','张某、安居住房服务有限公司','张某与安居住房服务有限公司因门禁变更发生争议。小区夜间关闭部分入口，租客认为通勤条件明显变化。主要证据为物业公告说明入口调整属于阶段性管理措施。','小区夜间关闭部分入口，租客认为通勤条件明显变化。庭审材料显示，物业公告说明入口调整属于阶段性管理措施。双方对合同相关条款的解释不一致。','判断门禁变更是否影响合同履行，需要比较看房时披露内容、公告时间和实际通行情况。物业公告说明入口调整属于阶段性管理措施。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,门禁变更,书面证据,物业公告说明入口调整属于阶段性管理措施');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_ac847ce22c','（2023）京仲4589号','李某与明远资产管理有限公司付款账户纠纷','court_bjac','合同纠纷','付款账户','2023-09-18','李某、明远资产管理有限公司','本案处理付款账户问题：出租方临时要求改向个人账户付款，租客拒绝后产生争议；庭审中提交了原合同和历史流水均指向另一账户。','出租方临时要求改向个人账户付款，租客拒绝后产生争议。庭审材料显示，原合同和历史流水均指向另一账户。双方对合同相关条款的解释不一致。','法院围绕付款账户审查书面条款、沟通时间和资金流，注意到原合同和历史流水均指向另一账户。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,付款账户,书面证据,原合同和历史流水均指向另一账户');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_c4488fdac6','（2023）京民初4626号','王某与京北房屋经纪有限公司租期衔接纠纷','court_cp','合同纠纷','租期衔接','2023-10-11','王某、京北房屋经纪有限公司','京北房屋经纪有限公司与王某对租期衔接的责任范围意见不一。查明事实为新租约起始日与旧租约终止日重叠，证据包括双方对钥匙和租金按日结算未达成一致。','新租约起始日与旧租约终止日重叠。庭审材料显示，双方对钥匙和租金按日结算未达成一致。双方对合同相关条款的解释不一致。','主张租期衔接的一方需说明计算方式和合同依据；现有证据中，双方对钥匙和租金按日结算未达成一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持王某的请求，具体金额以判决主文为准。','部分支持','租赁,租期衔接,书面证据,双方对钥匙和租金按日结算未达成一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_cd17a6c647','（2023）京民初4663号','赵某与瑞景物业管理有限公司家具损坏纠纷','court_sjs','合同纠纷','家具损坏','2023-11-03','赵某、瑞景物业管理有限公司','争议源于退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。赵某据此主张处理家具损坏，并提交交接照片显示铰链此前已有松动。','退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。庭审材料显示，交接照片显示铰链此前已有松动。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断家具损坏责任。交接照片显示铰链此前已有松动。','经调解，双方就家具损坏的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,家具损坏,书面证据,交接照片显示铰链此前已有松动');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_c759c461d0','（2023）京民初4700号','陈某与海淀住房租赁管理有限公司物业维修纠纷','court_hd','其他','物业维修','2023-11-26','陈某、海淀住房租赁管理有限公司','围绕物业维修，双方确认租赁关系存在，但对费用和责任有分歧。公共排水堵塞造成室内返水，物业与出租方争议责任分担；维修记录显示堵点位于公共立管。','公共排水堵塞造成室内返水，物业与出租方争议责任分担。庭审材料显示，维修记录显示堵点位于公共立管。双方对合同相关条款的解释不一致。','处理物业维修需要区分自然损耗、公共部位责任和不当使用。现有材料显示，维修记录显示堵点位于公共立管。','对有书面凭证支持的物业维修主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,物业维修,书面证据,维修记录显示堵点位于公共立管');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_39ac579241','（2023）京民初4737号','周某与清河物业服务中心转租授权纠纷','court_xc','合同纠纷','转租授权','2023-12-19','周某、清河物业服务中心','周某起诉要求解决转租授权。案件材料记载二房东签约后无法提供原出租人的转租同意，其中主合同中存在禁止转租条款。','二房东签约后无法提供原出租人的转租同意。庭审材料显示，主合同中存在禁止转租条款。双方对合同相关条款的解释不一致。','对于转租授权，不能只凭口头说明，应结合可追溯的书面材料。现有材料表明，主合同中存在禁止转租条款。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,转租授权,书面证据,主合同中存在禁止转租条款');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_7021092e39','（2024）京仲4774号','孙某与诚家房地产经纪中心经纪服务费纠纷','court_bjac','合同纠纷','经纪服务费','2024-01-11','孙某、诚家房地产经纪中心','经纪服务费是本案主要争点。经纪人在签约前后对服务费口径表述不一致，双方分别就平台页面和聊天记录显示收费项目发生变化发表意见。','经纪人在签约前后对服务费口径表述不一致。庭审材料显示，平台页面和聊天记录显示收费项目发生变化。双方对合同相关条款的解释不一致。','经纪服务费应先看合同约定，再核对实际付款、退款条件和金额凭证。平台页面和聊天记录显示收费项目发生变化。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,经纪服务费,书面证据,平台页面和聊天记录显示收费项目发生变化');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_4edebb551e','（2024）京民初4811号','刘某与上地公寓运营中心定金性质纠纷','court_cp','合同纠纷','定金性质','2024-02-03','刘某、上地公寓运营中心','案件发生在租赁履行期间。付款备注写作意向金，收据写作定金，双方争议退款条件；与定金性质相关的材料包括付款前后文本对款项用途表述不一致。','付款备注写作意向金，收据写作定金，双方争议退款条件。庭审材料显示，付款前后文本对款项用途表述不一致。双方对合同相关条款的解释不一致。','法院围绕定金性质审查书面条款、沟通时间和资金流，注意到付款前后文本对款项用途表述不一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持刘某的请求，具体金额以判决主文为准。','部分支持','租赁,定金性质,书面证据,付款前后文本对款项用途表述不一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_afda29fb3b','（2024）京民初4848号','高某与安居住房服务有限公司清洁费用纠纷','court_sjs','合同纠纷','清洁费用','2024-02-26','高某、安居住房服务有限公司','高某与安居住房服务有限公司对清洁费用协商未果。已查明合同只写恢复整洁，退租时出租方主张高额深度清洁费，并有出租方未提供实际清洁发票佐证。','合同只写恢复整洁，退租时出租方主张高额深度清洁费。庭审材料显示，出租方未提供实际清洁发票。双方对合同相关条款的解释不一致。','主张清洁费用的一方需说明计算方式和合同依据；现有证据中，出租方未提供实际清洁发票。','经调解，双方就清洁费用的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,清洁费用,书面证据,出租方未提供实际清洁发票');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_97f7118df8','（2024）京民初4885号','林某与明远资产管理有限公司押金返还纠纷','court_hd','合同纠纷','押金返还','2024-03-20','林某、明远资产管理有限公司','法院审理的核心是押金返还。退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围，现有书面材料中包含租客提交入住照片、退租视频和保洁票据。','退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围。庭审材料显示，租客提交入住照片、退租视频和保洁票据。双方对合同相关条款的解释不一致。','押金返还应先看合同约定，再核对实际付款、退款条件和金额凭证。租客提交入住照片、退租视频和保洁票据。','对有书面凭证支持的押金返还主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,押金返还,书面证据,租客提交入住照片、退租视频和保洁票据');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_dcde02002e','（2024）京民初4922号','许某与京北房屋经纪有限公司噪声影响纠纷','court_xc','合同纠纷','噪声影响','2024-04-12','许某、京北房屋经纪有限公司','双方合同履行过程中出现噪声影响争议。出租前未披露相邻施工，租客入住后主张影响正常居住；证据链以施工公告和看房时间能够证明披露范围为主。','出租前未披露相邻施工，租客入住后主张影响正常居住。庭审材料显示，施工公告和看房时间能够证明披露范围。双方对合同相关条款的解释不一致。','法院结合物业公告、现场路线和新增费用审查噪声影响，其中施工公告和看房时间能够证明披露范围。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,噪声影响,书面证据,施工公告和看房时间能够证明披露范围');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_23456831f4','（2024）京民终4959号','韩某与瑞景物业管理有限公司租金调整纠纷','court_bj2','合同纠纷','租金调整','2024-05-05','韩某、瑞景物业管理有限公司','该案涉及租金调整及相应费用承担。续租报价在短期内多次变化，租客主张应按较早报价履行，提交的关键材料为邮件中未出现明确接受或签署记录。','续租报价在短期内多次变化，租客主张应按较早报价履行。庭审材料显示，邮件中未出现明确接受或签署记录。双方对合同相关条款的解释不一致。','主张租金调整的一方需说明计算方式和合同依据；现有证据中，邮件中未出现明确接受或签署记录。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,租金调整,书面证据,邮件中未出现明确接受或签署记录');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_72bdc3135a','（2024）京民初4996号','杜某与海淀住房租赁管理有限公司搬家通道纠纷','court_cy','其他','搬家通道','2024-05-28','杜某、海淀住房租赁管理有限公司','杜某与海淀住房租赁管理有限公司因搬家通道发生争议。物业临时封闭车库通道，租客增加搬运费用。主要证据为公告发布时间晚于搬家公司预约时间。','物业临时封闭车库通道，租客增加搬运费用。庭审材料显示，公告发布时间晚于搬家公司预约时间。双方对合同相关条款的解释不一致。','判断搬家通道是否影响合同履行，需要比较看房时披露内容、公告时间和实际通行情况。公告发布时间晚于搬家公司预约时间。','双方应按合同及已核实履行事实承担相应责任。','部分支持杜某的请求，具体金额以判决主文为准。','部分支持','租赁,搬家通道,书面证据,公告发布时间晚于搬家公司预约时间');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_cd0695c349','（2024）京民初5033号','顾某与清河物业服务中心出租权限纠纷','court_ft','合同纠纷','出租权限','2024-06-20','顾某、清河物业服务中心','本案处理出租权限问题：签约人并非产权登记人，双方争议其是否取得有效委托；庭审中提交了委托书、产权材料和收款账户是争议焦点。','签约人并非产权登记人，双方争议其是否取得有效委托。庭审材料显示，委托书、产权材料和收款账户是争议焦点。双方对合同相关条款的解释不一致。','法院核对主体身份、授权文件和资料用途后处理出租权限；委托书、产权材料和收款账户是争议焦点。','经调解，双方就出租权限的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,出租权限,书面证据,委托书、产权材料和收款账户是争议焦点');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_5c600d2a19','（2024）京仲5070号','叶某与诚家房地产经纪中心租赁登记纠纷','court_bjac','合同纠纷','租赁登记','2024-07-13','叶某、诚家房地产经纪中心','诚家房地产经纪中心与叶某对租赁登记的责任范围意见不一。查明事实为合同未约定由谁准备登记材料，入住后双方相互推诿，证据包括社区窗口清单能够说明所需材料。','合同未约定由谁准备登记材料，入住后双方相互推诿。庭审材料显示，社区窗口清单能够说明所需材料。双方对合同相关条款的解释不一致。','对于租赁登记，不能只凭口头说明，应结合可追溯的书面材料。现有材料表明，社区窗口清单能够说明所需材料。','对有书面凭证支持的租赁登记主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,租赁登记,书面证据,社区窗口清单能够说明所需材料');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_7b10647a25','（2024）京民初5107号','唐某与上地公寓运营中心看房承诺纠纷','court_cp','合同纠纷','看房承诺','2024-08-05','唐某、上地公寓运营中心','争议源于经纪人口头承诺可养宠物，合同草案却明确禁止。唐某据此主张处理看房承诺，并提交录音、平台详情和草案内容彼此冲突。','经纪人口头承诺可养宠物，合同草案却明确禁止。庭审材料显示，录音、平台详情和草案内容彼此冲突。双方对合同相关条款的解释不一致。','处理看房承诺应比较合同草案、交接记录和双方沟通。录音、平台详情和草案内容彼此冲突。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,看房承诺,书面证据,录音、平台详情和草案内容彼此冲突');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_69cf98bdc5','（2024）京民初5144号','张某与安居住房服务有限公司外墙渗水纠纷','court_sjs','合同纠纷','外墙渗水','2024-08-28','张某、安居住房服务有限公司','围绕外墙渗水，双方确认租赁关系存在，但对费用和责任有分歧。暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关；物业工单、气象记录和墙面照片能够相互印证。','暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关。庭审材料显示，物业工单、气象记录和墙面照片能够相互印证。双方对合同相关条款的解释不一致。','处理外墙渗水需要区分自然损耗、公共部位责任和不当使用。现有材料显示，物业工单、气象记录和墙面照片能够相互印证。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,外墙渗水,书面证据,物业工单、气象记录和墙面照片能够相互印证');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_05b540a379','（2024）京民初5181号','李某与明远资产管理有限公司供暖结算纠纷','court_hd','合同纠纷','供暖结算','2024-09-20','李某、明远资产管理有限公司','李某起诉要求解决供暖结算。案件材料记载租期跨越供暖季，预收供暖费的退还方式没有写清，其中缴费凭证和合同附件对结算周期记载不同。','租期跨越供暖季，预收供暖费的退还方式没有写清。庭审材料显示，缴费凭证和合同附件对结算周期记载不同。双方对合同相关条款的解释不一致。','主张供暖结算的一方需说明计算方式和合同依据；现有证据中，缴费凭证和合同附件对结算周期记载不同。','双方应按合同及已核实履行事实承担相应责任。','部分支持李某的请求，具体金额以判决主文为准。','部分支持','租赁,供暖结算,书面证据,缴费凭证和合同附件对结算周期记载不同');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_95ff912c7f','（2024）京民初5218号','王某与京北房屋经纪有限公司钥匙交接纠纷','court_xc','合同纠纷','钥匙交接','2024-10-13','王某、京北房屋经纪有限公司','钥匙交接是本案主要争点。交房时钥匙数量与退租清单不一致，双方分别就双方签字的交接单只列明三把钥匙发表意见。','交房时钥匙数量与退租清单不一致。庭审材料显示，双方签字的交接单只列明三把钥匙。双方对合同相关条款的解释不一致。','处理钥匙交接应比较合同草案、交接记录和双方沟通。双方签字的交接单只列明三把钥匙。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,钥匙交接,书面证据,双方签字的交接单只列明三把钥匙');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_d2601dc9f8','（2024）京民终5255号','赵某与瑞景物业管理有限公司发票开具纠纷','court_bj2','合同纠纷','发票开具','2024-11-05','赵某、瑞景物业管理有限公司','案件发生在租赁履行期间。机构收取服务费后长期未开具发票；与发票开具相关的材料包括付款记录和多次催办邮件可以核实。','机构收取服务费后长期未开具发票。庭审材料显示，付款记录和多次催办邮件可以核实。双方对合同相关条款的解释不一致。','法院围绕发票开具审查书面条款、沟通时间和资金流，注意到付款记录和多次催办邮件可以核实。','双方应按合同及已核实履行事实承担相应责任。','部分支持赵某的请求，具体金额以判决主文为准。','部分支持','租赁,发票开具,书面证据,付款记录和多次催办邮件可以核实');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_c5fcc3f8e5','（2024）京民初5292号','陈某与海淀住房租赁管理有限公司家具损坏纠纷','court_cy','合同纠纷','家具损坏','2024-11-28','陈某、海淀住房租赁管理有限公司','陈某与海淀住房租赁管理有限公司对家具损坏协商未果。已查明退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用，并有交接照片显示铰链此前已有松动佐证。','退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。庭审材料显示，交接照片显示铰链此前已有松动。双方对合同相关条款的解释不一致。','关于家具损坏，工单、检测报告和现场照片比单方陈述更能还原经过；交接照片显示铰链此前已有松动。','经调解，双方就家具损坏的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,家具损坏,书面证据,交接照片显示铰链此前已有松动');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_e9a620afab','（2024）京民初5329号','周某与清河物业服务中心物业维修纠纷','court_ft','其他','物业维修','2024-12-21','周某、清河物业服务中心','法院审理的核心是物业维修。公共排水堵塞造成室内返水，物业与出租方争议责任分担，现有书面材料中包含维修记录显示堵点位于公共立管。','公共排水堵塞造成室内返水，物业与出租方争议责任分担。庭审材料显示，维修记录显示堵点位于公共立管。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断物业维修责任。维修记录显示堵点位于公共立管。','对有书面凭证支持的物业维修主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,物业维修,书面证据,维修记录显示堵点位于公共立管');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_50d86cbe7c','（2025）京仲5366号','孙某与诚家房地产经纪中心转租授权纠纷','court_bjac','合同纠纷','转租授权','2025-01-13','孙某、诚家房地产经纪中心','双方合同履行过程中出现转租授权争议。二房东签约后无法提供原出租人的转租同意；证据链以主合同中存在禁止转租条款为主。','二房东签约后无法提供原出租人的转租同意。庭审材料显示，主合同中存在禁止转租条款。双方对合同相关条款的解释不一致。','法院核对主体身份、授权文件和资料用途后处理转租授权；主合同中存在禁止转租条款。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,转租授权,书面证据,主合同中存在禁止转租条款');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_902039fab3','（2025）京民初5403号','刘某与上地公寓运营中心经纪服务费纠纷','court_xc','合同纠纷','经纪服务费','2025-02-05','刘某、上地公寓运营中心','该案涉及经纪服务费及相应费用承担。经纪人在签约前后对服务费口径表述不一致，提交的关键材料为平台页面和聊天记录显示收费项目发生变化。','经纪人在签约前后对服务费口径表述不一致。庭审材料显示，平台页面和聊天记录显示收费项目发生变化。双方对合同相关条款的解释不一致。','主张经纪服务费的一方需说明计算方式和合同依据；现有证据中，平台页面和聊天记录显示收费项目发生变化。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,经纪服务费,书面证据,平台页面和聊天记录显示收费项目发生变化');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_44928549fd','（2025）京民终5440号','高某与安居住房服务有限公司定金性质纠纷','court_bj2','合同纠纷','定金性质','2025-02-28','高某、安居住房服务有限公司','高某与安居住房服务有限公司因定金性质发生争议。付款备注写作意向金，收据写作定金，双方争议退款条件。主要证据为付款前后文本对款项用途表述不一致。','付款备注写作意向金，收据写作定金，双方争议退款条件。庭审材料显示，付款前后文本对款项用途表述不一致。双方对合同相关条款的解释不一致。','定金性质应先看合同约定，再核对实际付款、退款条件和金额凭证。付款前后文本对款项用途表述不一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持高某的请求，具体金额以判决主文为准。','部分支持','租赁,定金性质,书面证据,付款前后文本对款项用途表述不一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_d43232b239','（2025）京民初5477号','林某与明远资产管理有限公司电器折旧纠纷','court_cy','合同纠纷','电器折旧','2025-03-23','林某、明远资产管理有限公司','本案处理电器折旧问题：空调压缩机故障后出租方要求租客承担全部更换费；庭审中提交了检测报告认为设备已接近设计寿命。','空调压缩机故障后出租方要求租客承担全部更换费。庭审材料显示，检测报告认为设备已接近设计寿命。双方对合同相关条款的解释不一致。','处理电器折旧需要区分自然损耗、公共部位责任和不当使用。现有材料显示，检测报告认为设备已接近设计寿命。','经调解，双方就电器折旧的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,电器折旧,书面证据,检测报告认为设备已接近设计寿命');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_dc2d35f518','（2025）京民初5514号','许某与京北房屋经纪有限公司维修垫付纠纷','court_ft','合同纠纷','维修垫付','2025-04-15','许某、京北房屋经纪有限公司','京北房屋经纪有限公司与许某对维修垫付的责任范围意见不一。查明事实为热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议，证据包括报修工单显示故障发生后当天通知房东。','热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议。庭审材料显示，报修工单显示故障发生后当天通知房东。双方对合同相关条款的解释不一致。','关于维修垫付，工单、检测报告和现场照片比单方陈述更能还原经过；报修工单显示故障发生后当天通知房东。','对有书面凭证支持的维修垫付主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,维修垫付,书面证据,报修工单显示故障发生后当天通知房东');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_bc7cb96465','（2025）京仲5551号','韩某与瑞景物业管理有限公司门禁变更纠纷','court_bjac','其他','门禁变更','2025-05-08','韩某、瑞景物业管理有限公司','争议源于小区夜间关闭部分入口，租客认为通勤条件明显变化。韩某据此主张处理门禁变更，并提交物业公告说明入口调整属于阶段性管理措施。','小区夜间关闭部分入口，租客认为通勤条件明显变化。庭审材料显示，物业公告说明入口调整属于阶段性管理措施。双方对合同相关条款的解释不一致。','判断门禁变更是否影响合同履行，需要比较看房时披露内容、公告时间和实际通行情况。物业公告说明入口调整属于阶段性管理措施。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,门禁变更,书面证据,物业公告说明入口调整属于阶段性管理措施');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_f0a2bc5432','（2025）京民初5588号','杜某与海淀住房租赁管理有限公司付款账户纠纷','court_cp','合同纠纷','付款账户','2025-05-31','杜某、海淀住房租赁管理有限公司','围绕付款账户，双方确认租赁关系存在，但对费用和责任有分歧。出租方临时要求改向个人账户付款，租客拒绝后产生争议；原合同和历史流水均指向另一账户。','出租方临时要求改向个人账户付款，租客拒绝后产生争议。庭审材料显示，原合同和历史流水均指向另一账户。双方对合同相关条款的解释不一致。','法院围绕付款账户审查书面条款、沟通时间和资金流，注意到原合同和历史流水均指向另一账户。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,付款账户,书面证据,原合同和历史流水均指向另一账户');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b0443c4694','（2025）京民初5625号','顾某与清河物业服务中心租期衔接纠纷','court_sjs','合同纠纷','租期衔接','2025-06-23','顾某、清河物业服务中心','顾某起诉要求解决租期衔接。案件材料记载新租约起始日与旧租约终止日重叠，其中双方对钥匙和租金按日结算未达成一致。','新租约起始日与旧租约终止日重叠。庭审材料显示，双方对钥匙和租金按日结算未达成一致。双方对合同相关条款的解释不一致。','主张租期衔接的一方需说明计算方式和合同依据；现有证据中，双方对钥匙和租金按日结算未达成一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持顾某的请求，具体金额以判决主文为准。','部分支持','租赁,租期衔接,书面证据,双方对钥匙和租金按日结算未达成一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_ea9e3f4c64','（2025）京民初5662号','叶某与诚家房地产经纪中心提前解约纠纷','court_hd','合同纠纷','提前解约','2025-07-16','叶某、诚家房地产经纪中心','提前解约是本案主要争点。租客因工作地点变化提前退租，合同约定与补充协议表述不一致，双方分别就双方邮件对解约通知期有不同理解发表意见。','租客因工作地点变化提前退租，合同约定与补充协议表述不一致。庭审材料显示，双方邮件对解约通知期有不同理解。双方对合同相关条款的解释不一致。','提前解约应先看合同约定，再核对实际付款、退款条件和金额凭证。双方邮件对解约通知期有不同理解。','经调解，双方就提前解约的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,提前解约,书面证据,双方邮件对解约通知期有不同理解');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_21a30fc60f','（2025）京民初5699号','唐某与上地公寓运营中心租赁登记纠纷','court_xc','合同纠纷','租赁登记','2025-08-08','唐某、上地公寓运营中心','案件发生在租赁履行期间。合同未约定由谁准备登记材料，入住后双方相互推诿；与租赁登记相关的材料包括社区窗口清单能够说明所需材料。','合同未约定由谁准备登记材料，入住后双方相互推诿。庭审材料显示，社区窗口清单能够说明所需材料。双方对合同相关条款的解释不一致。','法院核对主体身份、授权文件和资料用途后处理租赁登记；社区窗口清单能够说明所需材料。','对有书面凭证支持的租赁登记主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,租赁登记,书面证据,社区窗口清单能够说明所需材料');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_244a9a5851','（2025）京民终5736号','张某与安居住房服务有限公司看房承诺纠纷','court_bj2','合同纠纷','看房承诺','2025-08-31','张某、安居住房服务有限公司','张某与安居住房服务有限公司对看房承诺协商未果。已查明经纪人口头承诺可养宠物，合同草案却明确禁止，并有录音、平台详情和草案内容彼此冲突佐证。','经纪人口头承诺可养宠物，合同草案却明确禁止。庭审材料显示，录音、平台详情和草案内容彼此冲突。双方对合同相关条款的解释不一致。','看房承诺不能只依据一方回忆，应由交接单、录音或平台页面相互印证；录音、平台详情和草案内容彼此冲突。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,看房承诺,书面证据,录音、平台详情和草案内容彼此冲突');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_bdf509da7e','（2025）京民初5773号','李某与明远资产管理有限公司外墙渗水纠纷','court_cy','合同纠纷','外墙渗水','2025-09-23','李某、明远资产管理有限公司','法院审理的核心是外墙渗水。暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关，现有书面材料中包含物业工单、气象记录和墙面照片能够相互印证。','暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关。庭审材料显示，物业工单、气象记录和墙面照片能够相互印证。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断外墙渗水责任。物业工单、气象记录和墙面照片能够相互印证。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,外墙渗水,书面证据,物业工单、气象记录和墙面照片能够相互印证');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_21515e5935','（2025）京民初5810号','王某与京北房屋经纪有限公司供暖结算纠纷','court_ft','合同纠纷','供暖结算','2025-10-16','王某、京北房屋经纪有限公司','双方合同履行过程中出现供暖结算争议。租期跨越供暖季，预收供暖费的退还方式没有写清；证据链以缴费凭证和合同附件对结算周期记载不同为主。','租期跨越供暖季，预收供暖费的退还方式没有写清。庭审材料显示，缴费凭证和合同附件对结算周期记载不同。双方对合同相关条款的解释不一致。','法院围绕供暖结算审查书面条款、沟通时间和资金流，注意到缴费凭证和合同附件对结算周期记载不同。','双方应按合同及已核实履行事实承担相应责任。','部分支持王某的请求，具体金额以判决主文为准。','部分支持','租赁,供暖结算,书面证据,缴费凭证和合同附件对结算周期记载不同');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_60c0ee9fea','（2025）京仲5847号','赵某与瑞景物业管理有限公司钥匙交接纠纷','court_bjac','合同纠纷','钥匙交接','2025-11-08','赵某、瑞景物业管理有限公司','该案涉及钥匙交接及相应费用承担。交房时钥匙数量与退租清单不一致，提交的关键材料为双方签字的交接单只列明三把钥匙。','交房时钥匙数量与退租清单不一致。庭审材料显示，双方签字的交接单只列明三把钥匙。双方对合同相关条款的解释不一致。','钥匙交接不能只依据一方回忆，应由交接单、录音或平台页面相互印证；双方签字的交接单只列明三把钥匙。','经调解，双方就钥匙交接的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,钥匙交接,书面证据,双方签字的交接单只列明三把钥匙');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_6c9303fac6','（2025）京民初5884号','陈某与海淀住房租赁管理有限公司押金返还纠纷','court_cp','合同纠纷','押金返还','2025-12-01','陈某、海淀住房租赁管理有限公司','陈某与海淀住房租赁管理有限公司因押金返还发生争议。退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围。主要证据为租客提交入住照片、退租视频和保洁票据。','退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围。庭审材料显示，租客提交入住照片、退租视频和保洁票据。双方对合同相关条款的解释不一致。','押金返还应先看合同约定，再核对实际付款、退款条件和金额凭证。租客提交入住照片、退租视频和保洁票据。','对有书面凭证支持的押金返还主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,押金返还,书面证据,租客提交入住照片、退租视频和保洁票据');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_410a3310ae','（2025）京民初5921号','周某与清河物业服务中心噪声影响纠纷','court_sjs','合同纠纷','噪声影响','2025-12-24','周某、清河物业服务中心','本案处理噪声影响问题：出租前未披露相邻施工，租客入住后主张影响正常居住；庭审中提交了施工公告和看房时间能够证明披露范围。','出租前未披露相邻施工，租客入住后主张影响正常居住。庭审材料显示，施工公告和看房时间能够证明披露范围。双方对合同相关条款的解释不一致。','法院结合物业公告、现场路线和新增费用审查噪声影响，其中施工公告和看房时间能够证明披露范围。','经调解，双方就噪声影响的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,噪声影响,书面证据,施工公告和看房时间能够证明披露范围');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b6485ce1cd','（2026）京民初5958号','孙某与诚家房地产经纪中心租金调整纠纷','court_hd','合同纠纷','租金调整','2026-01-16','孙某、诚家房地产经纪中心','诚家房地产经纪中心与孙某对租金调整的责任范围意见不一。查明事实为续租报价在短期内多次变化，租客主张应按较早报价履行，证据包括邮件中未出现明确接受或签署记录。','续租报价在短期内多次变化，租客主张应按较早报价履行。庭审材料显示，邮件中未出现明确接受或签署记录。双方对合同相关条款的解释不一致。','主张租金调整的一方需说明计算方式和合同依据；现有证据中，邮件中未出现明确接受或签署记录。','对有书面凭证支持的租金调整主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,租金调整,书面证据,邮件中未出现明确接受或签署记录');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_3f94beb540','（2026）京民初5995号','刘某与上地公寓运营中心搬家通道纠纷','court_xc','其他','搬家通道','2026-02-08','刘某、上地公寓运营中心','争议源于物业临时封闭车库通道，租客增加搬运费用。刘某据此主张处理搬家通道，并提交公告发布时间晚于搬家公司预约时间。','物业临时封闭车库通道，租客增加搬运费用。庭审材料显示，公告发布时间晚于搬家公司预约时间。双方对合同相关条款的解释不一致。','判断搬家通道是否影响合同履行，需要比较看房时披露内容、公告时间和实际通行情况。公告发布时间晚于搬家公司预约时间。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,搬家通道,书面证据,公告发布时间晚于搬家公司预约时间');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_4ad615855e','（2026）京仲6032号','高某与安居住房服务有限公司出租权限纠纷','court_bjac','合同纠纷','出租权限','2026-03-03','高某、安居住房服务有限公司','围绕出租权限，双方确认租赁关系存在，但对费用和责任有分歧。签约人并非产权登记人，双方争议其是否取得有效委托；委托书、产权材料和收款账户是争议焦点。','签约人并非产权登记人，双方争议其是否取得有效委托。庭审材料显示，委托书、产权材料和收款账户是争议焦点。双方对合同相关条款的解释不一致。','法院核对主体身份、授权文件和资料用途后处理出租权限；委托书、产权材料和收款账户是争议焦点。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,出租权限,书面证据,委托书、产权材料和收款账户是争议焦点');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_3b37ec20ae','（2026）京民初6069号','林某与明远资产管理有限公司个人信息纠纷','court_cp','侵权责任','个人信息','2026-03-26','林某、明远资产管理有限公司','林某起诉要求解决个人信息。案件材料记载经纪人要求提前发送身份证和收入证明，租客质疑收集范围，其中机构未能说明资料保存期限和接收人员。','经纪人要求提前发送身份证和收入证明，租客质疑收集范围。庭审材料显示，机构未能说明资料保存期限和接收人员。双方对合同相关条款的解释不一致。','对于个人信息，不能只凭口头说明，应结合可追溯的书面材料。现有材料表明，机构未能说明资料保存期限和接收人员。','双方应按合同及已核实履行事实承担相应责任。','部分支持林某的请求，具体金额以判决主文为准。','部分支持','租赁,个人信息,书面证据,机构未能说明资料保存期限和接收人员');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_55a6023467','（2026）京民初6106号','许某与京北房屋经纪有限公司电器折旧纠纷','court_sjs','合同纠纷','电器折旧','2026-04-18','许某、京北房屋经纪有限公司','电器折旧是本案主要争点。空调压缩机故障后出租方要求租客承担全部更换费，双方分别就检测报告认为设备已接近设计寿命发表意见。','空调压缩机故障后出租方要求租客承担全部更换费。庭审材料显示，检测报告认为设备已接近设计寿命。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断电器折旧责任。检测报告认为设备已接近设计寿命。','经调解，双方就电器折旧的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,电器折旧,书面证据,检测报告认为设备已接近设计寿命');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_87fd22f71b','（2026）京民初6143号','韩某与瑞景物业管理有限公司维修垫付纠纷','court_hd','合同纠纷','维修垫付','2026-05-11','韩某、瑞景物业管理有限公司','案件发生在租赁履行期间。热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议；与维修垫付相关的材料包括报修工单显示故障发生后当天通知房东。','热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议。庭审材料显示，报修工单显示故障发生后当天通知房东。双方对合同相关条款的解释不一致。','处理维修垫付需要区分自然损耗、公共部位责任和不当使用。现有材料显示，报修工单显示故障发生后当天通知房东。','对有书面凭证支持的维修垫付主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,维修垫付,书面证据,报修工单显示故障发生后当天通知房东');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_c716f7fdb7','（2022）京民初6180号','杜某与海淀住房租赁管理有限公司门禁变更纠纷','court_xc','其他','门禁变更','2022-01-05','杜某、海淀住房租赁管理有限公司','杜某与海淀住房租赁管理有限公司对门禁变更协商未果。已查明小区夜间关闭部分入口，租客认为通勤条件明显变化，并有物业公告说明入口调整属于阶段性管理措施佐证。','小区夜间关闭部分入口，租客认为通勤条件明显变化。庭审材料显示，物业公告说明入口调整属于阶段性管理措施。双方对合同相关条款的解释不一致。','门禁变更的责任范围取决于变化是否可预见以及是否造成实际损失；物业公告说明入口调整属于阶段性管理措施。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,门禁变更,书面证据,物业公告说明入口调整属于阶段性管理措施');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_25394018bb','（2022）京民终6217号','顾某与清河物业服务中心付款账户纠纷','court_bj2','合同纠纷','付款账户','2022-01-28','顾某、清河物业服务中心','法院审理的核心是付款账户。出租方临时要求改向个人账户付款，租客拒绝后产生争议，现有书面材料中包含原合同和历史流水均指向另一账户。','出租方临时要求改向个人账户付款，租客拒绝后产生争议。庭审材料显示，原合同和历史流水均指向另一账户。双方对合同相关条款的解释不一致。','付款账户应先看合同约定，再核对实际付款、退款条件和金额凭证。原合同和历史流水均指向另一账户。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,付款账户,书面证据,原合同和历史流水均指向另一账户');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_62170832a1','（2022）京民初6254号','叶某与诚家房地产经纪中心租期衔接纠纷','court_cy','合同纠纷','租期衔接','2022-02-20','叶某、诚家房地产经纪中心','双方合同履行过程中出现租期衔接争议。新租约起始日与旧租约终止日重叠；证据链以双方对钥匙和租金按日结算未达成一致为主。','新租约起始日与旧租约终止日重叠。庭审材料显示，双方对钥匙和租金按日结算未达成一致。双方对合同相关条款的解释不一致。','法院围绕租期衔接审查书面条款、沟通时间和资金流，注意到双方对钥匙和租金按日结算未达成一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持叶某的请求，具体金额以判决主文为准。','部分支持','租赁,租期衔接,书面证据,双方对钥匙和租金按日结算未达成一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_668eb4f04a','（2022）京民初6291号','唐某与上地公寓运营中心家具损坏纠纷','court_ft','合同纠纷','家具损坏','2022-03-15','唐某、上地公寓运营中心','该案涉及家具损坏及相应费用承担。退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用，提交的关键材料为交接照片显示铰链此前已有松动。','退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。庭审材料显示，交接照片显示铰链此前已有松动。双方对合同相关条款的解释不一致。','关于家具损坏，工单、检测报告和现场照片比单方陈述更能还原经过；交接照片显示铰链此前已有松动。','经调解，双方就家具损坏的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,家具损坏,书面证据,交接照片显示铰链此前已有松动');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_7769312b9c','（2022）京仲6328号','张某与安居住房服务有限公司物业维修纠纷','court_bjac','其他','物业维修','2022-04-07','张某、安居住房服务有限公司','张某与安居住房服务有限公司因物业维修发生争议。公共排水堵塞造成室内返水，物业与出租方争议责任分担。主要证据为维修记录显示堵点位于公共立管。','公共排水堵塞造成室内返水，物业与出租方争议责任分担。庭审材料显示，维修记录显示堵点位于公共立管。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断物业维修责任。维修记录显示堵点位于公共立管。','对有书面凭证支持的物业维修主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,物业维修,书面证据,维修记录显示堵点位于公共立管');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_1c59099a0f','（2022）京民初6365号','李某与明远资产管理有限公司转租授权纠纷','court_cp','合同纠纷','转租授权','2022-04-30','李某、明远资产管理有限公司','本案处理转租授权问题：二房东签约后无法提供原出租人的转租同意；庭审中提交了主合同中存在禁止转租条款。','二房东签约后无法提供原出租人的转租同意。庭审材料显示，主合同中存在禁止转租条款。双方对合同相关条款的解释不一致。','法院核对主体身份、授权文件和资料用途后处理转租授权；主合同中存在禁止转租条款。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,转租授权,书面证据,主合同中存在禁止转租条款');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_380d7ddaab','（2022）京民初6402号','王某与京北房屋经纪有限公司经纪服务费纠纷','court_sjs','合同纠纷','经纪服务费','2022-05-23','王某、京北房屋经纪有限公司','京北房屋经纪有限公司与王某对经纪服务费的责任范围意见不一。查明事实为经纪人在签约前后对服务费口径表述不一致，证据包括平台页面和聊天记录显示收费项目发生变化。','经纪人在签约前后对服务费口径表述不一致。庭审材料显示，平台页面和聊天记录显示收费项目发生变化。双方对合同相关条款的解释不一致。','主张经纪服务费的一方需说明计算方式和合同依据；现有证据中，平台页面和聊天记录显示收费项目发生变化。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,经纪服务费,书面证据,平台页面和聊天记录显示收费项目发生变化');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_69343ab8b0','（2022）京民初6439号','赵某与瑞景物业管理有限公司定金性质纠纷','court_hd','合同纠纷','定金性质','2022-06-15','赵某、瑞景物业管理有限公司','争议源于付款备注写作意向金，收据写作定金，双方争议退款条件。赵某据此主张处理定金性质，并提交付款前后文本对款项用途表述不一致。','付款备注写作意向金，收据写作定金，双方争议退款条件。庭审材料显示，付款前后文本对款项用途表述不一致。双方对合同相关条款的解释不一致。','定金性质应先看合同约定，再核对实际付款、退款条件和金额凭证。付款前后文本对款项用途表述不一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持赵某的请求，具体金额以判决主文为准。','部分支持','租赁,定金性质,书面证据,付款前后文本对款项用途表述不一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b9afe48c40','（2022）京民初6476号','陈某与海淀住房租赁管理有限公司清洁费用纠纷','court_xc','合同纠纷','清洁费用','2022-07-08','陈某、海淀住房租赁管理有限公司','围绕清洁费用，双方确认租赁关系存在，但对费用和责任有分歧。合同只写恢复整洁，退租时出租方主张高额深度清洁费；出租方未提供实际清洁发票。','合同只写恢复整洁，退租时出租方主张高额深度清洁费。庭审材料显示，出租方未提供实际清洁发票。双方对合同相关条款的解释不一致。','法院围绕清洁费用审查书面条款、沟通时间和资金流，注意到出租方未提供实际清洁发票。','经调解，双方就清洁费用的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,清洁费用,书面证据,出租方未提供实际清洁发票');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_7730f11426','（2022）京民终6513号','周某与清河物业服务中心押金返还纠纷','court_bj2','合同纠纷','押金返还','2022-07-31','周某、清河物业服务中心','周某起诉要求解决押金返还。案件材料记载退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围，其中租客提交入住照片、退租视频和保洁票据。','退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围。庭审材料显示，租客提交入住照片、退租视频和保洁票据。双方对合同相关条款的解释不一致。','主张押金返还的一方需说明计算方式和合同依据；现有证据中，租客提交入住照片、退租视频和保洁票据。','对有书面凭证支持的押金返还主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,押金返还,书面证据,租客提交入住照片、退租视频和保洁票据');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_d52b147a13','（2022）京民初6550号','孙某与诚家房地产经纪中心噪声影响纠纷','court_cy','合同纠纷','噪声影响','2022-08-23','孙某、诚家房地产经纪中心','噪声影响是本案主要争点。出租前未披露相邻施工，租客入住后主张影响正常居住，双方分别就施工公告和看房时间能够证明披露范围发表意见。','出租前未披露相邻施工，租客入住后主张影响正常居住。庭审材料显示，施工公告和看房时间能够证明披露范围。双方对合同相关条款的解释不一致。','判断噪声影响是否影响合同履行，需要比较看房时披露内容、公告时间和实际通行情况。施工公告和看房时间能够证明披露范围。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,噪声影响,书面证据,施工公告和看房时间能够证明披露范围');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_cada6cde10','（2022）京民初6587号','刘某与上地公寓运营中心租金调整纠纷','court_ft','合同纠纷','租金调整','2022-09-15','刘某、上地公寓运营中心','案件发生在租赁履行期间。续租报价在短期内多次变化，租客主张应按较早报价履行；与租金调整相关的材料包括邮件中未出现明确接受或签署记录。','续租报价在短期内多次变化，租客主张应按较早报价履行。庭审材料显示，邮件中未出现明确接受或签署记录。双方对合同相关条款的解释不一致。','法院围绕租金调整审查书面条款、沟通时间和资金流，注意到邮件中未出现明确接受或签署记录。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,租金调整,书面证据,邮件中未出现明确接受或签署记录');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_ed4c7a0062','（2022）京仲6624号','高某与安居住房服务有限公司搬家通道纠纷','court_bjac','其他','搬家通道','2022-10-08','高某、安居住房服务有限公司','高某与安居住房服务有限公司对搬家通道协商未果。已查明物业临时封闭车库通道，租客增加搬运费用，并有公告发布时间晚于搬家公司预约时间佐证。','物业临时封闭车库通道，租客增加搬运费用。庭审材料显示，公告发布时间晚于搬家公司预约时间。双方对合同相关条款的解释不一致。','搬家通道的责任范围取决于变化是否可预见以及是否造成实际损失；公告发布时间晚于搬家公司预约时间。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,搬家通道,书面证据,公告发布时间晚于搬家公司预约时间');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_9f5ea8853e','（2022）京民初6661号','林某与明远资产管理有限公司出租权限纠纷','court_xc','合同纠纷','出租权限','2022-10-31','林某、明远资产管理有限公司','法院审理的核心是出租权限。签约人并非产权登记人，双方争议其是否取得有效委托，现有书面材料中包含委托书、产权材料和收款账户是争议焦点。','签约人并非产权登记人，双方争议其是否取得有效委托。庭审材料显示，委托书、产权材料和收款账户是争议焦点。双方对合同相关条款的解释不一致。','出租权限取决于授权范围、材料来源和接收主体是否清楚。委托书、产权材料和收款账户是争议焦点。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,出租权限,书面证据,委托书、产权材料和收款账户是争议焦点');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_686e956191','（2022）京民终6698号','许某与京北房屋经纪有限公司租赁登记纠纷','court_bj2','合同纠纷','租赁登记','2022-11-23','许某、京北房屋经纪有限公司','双方合同履行过程中出现租赁登记争议。合同未约定由谁准备登记材料，入住后双方相互推诿；证据链以社区窗口清单能够说明所需材料为主。','合同未约定由谁准备登记材料，入住后双方相互推诿。庭审材料显示，社区窗口清单能够说明所需材料。双方对合同相关条款的解释不一致。','法院核对主体身份、授权文件和资料用途后处理租赁登记；社区窗口清单能够说明所需材料。','双方应按合同及已核实履行事实承担相应责任。','部分支持许某的请求，具体金额以判决主文为准。','部分支持','租赁,租赁登记,书面证据,社区窗口清单能够说明所需材料');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_3420211ef5','（2022）京民初6735号','韩某与瑞景物业管理有限公司看房承诺纠纷','court_cy','合同纠纷','看房承诺','2022-12-16','韩某、瑞景物业管理有限公司','该案涉及看房承诺及相应费用承担。经纪人口头承诺可养宠物，合同草案却明确禁止，提交的关键材料为录音、平台详情和草案内容彼此冲突。','经纪人口头承诺可养宠物，合同草案却明确禁止。庭审材料显示，录音、平台详情和草案内容彼此冲突。双方对合同相关条款的解释不一致。','看房承诺不能只依据一方回忆，应由交接单、录音或平台页面相互印证；录音、平台详情和草案内容彼此冲突。','经调解，双方就看房承诺的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,看房承诺,书面证据,录音、平台详情和草案内容彼此冲突');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_89ac9f0bf2','（2023）京民初6772号','杜某与海淀住房租赁管理有限公司外墙渗水纠纷','court_ft','合同纠纷','外墙渗水','2023-01-08','杜某、海淀住房租赁管理有限公司','杜某与海淀住房租赁管理有限公司因外墙渗水发生争议。暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关。主要证据为物业工单、气象记录和墙面照片能够相互印证。','暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关。庭审材料显示，物业工单、气象记录和墙面照片能够相互印证。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断外墙渗水责任。物业工单、气象记录和墙面照片能够相互印证。','对有书面凭证支持的外墙渗水主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,外墙渗水,书面证据,物业工单、气象记录和墙面照片能够相互印证');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_fb99335155','（2023）京仲6809号','顾某与清河物业服务中心供暖结算纠纷','court_bjac','合同纠纷','供暖结算','2023-01-31','顾某、清河物业服务中心','本案处理供暖结算问题：租期跨越供暖季，预收供暖费的退还方式没有写清；庭审中提交了缴费凭证和合同附件对结算周期记载不同。','租期跨越供暖季，预收供暖费的退还方式没有写清。庭审材料显示，缴费凭证和合同附件对结算周期记载不同。双方对合同相关条款的解释不一致。','法院围绕供暖结算审查书面条款、沟通时间和资金流，注意到缴费凭证和合同附件对结算周期记载不同。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,供暖结算,书面证据,缴费凭证和合同附件对结算周期记载不同');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b1fc61eb46','（2023）京民初6846号','叶某与诚家房地产经纪中心钥匙交接纠纷','court_cp','合同纠纷','钥匙交接','2023-02-23','叶某、诚家房地产经纪中心','诚家房地产经纪中心与叶某对钥匙交接的责任范围意见不一。查明事实为交房时钥匙数量与退租清单不一致，证据包括双方签字的交接单只列明三把钥匙。','交房时钥匙数量与退租清单不一致。庭审材料显示，双方签字的交接单只列明三把钥匙。双方对合同相关条款的解释不一致。','钥匙交接不能只依据一方回忆，应由交接单、录音或平台页面相互印证；双方签字的交接单只列明三把钥匙。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,钥匙交接,书面证据,双方签字的交接单只列明三把钥匙');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_4a77baaf17','（2023）京民初6883号','唐某与上地公寓运营中心发票开具纠纷','court_sjs','合同纠纷','发票开具','2023-03-18','唐某、上地公寓运营中心','争议源于机构收取服务费后长期未开具发票。唐某据此主张处理发票开具，并提交付款记录和多次催办邮件可以核实。','机构收取服务费后长期未开具发票。庭审材料显示，付款记录和多次催办邮件可以核实。双方对合同相关条款的解释不一致。','发票开具应先看合同约定，再核对实际付款、退款条件和金额凭证。付款记录和多次催办邮件可以核实。','双方应按合同及已核实履行事实承担相应责任。','部分支持唐某的请求，具体金额以判决主文为准。','部分支持','租赁,发票开具,书面证据,付款记录和多次催办邮件可以核实');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_db1f8c3a87','（2023）京民初6920号','张某与安居住房服务有限公司家具损坏纠纷','court_hd','合同纠纷','家具损坏','2023-04-10','张某、安居住房服务有限公司','围绕家具损坏，双方确认租赁关系存在，但对费用和责任有分歧。退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用；交接照片显示铰链此前已有松动。','退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。庭审材料显示，交接照片显示铰链此前已有松动。双方对合同相关条款的解释不一致。','处理家具损坏需要区分自然损耗、公共部位责任和不当使用。现有材料显示，交接照片显示铰链此前已有松动。','经调解，双方就家具损坏的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,家具损坏,书面证据,交接照片显示铰链此前已有松动');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_bd8a46662a','（2023）京民初6957号','李某与明远资产管理有限公司物业维修纠纷','court_xc','其他','物业维修','2023-05-03','李某、明远资产管理有限公司','李某起诉要求解决物业维修。案件材料记载公共排水堵塞造成室内返水，物业与出租方争议责任分担，其中维修记录显示堵点位于公共立管。','公共排水堵塞造成室内返水，物业与出租方争议责任分担。庭审材料显示，维修记录显示堵点位于公共立管。双方对合同相关条款的解释不一致。','关于物业维修，工单、检测报告和现场照片比单方陈述更能还原经过；维修记录显示堵点位于公共立管。','对有书面凭证支持的物业维修主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,物业维修,书面证据,维修记录显示堵点位于公共立管');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_a8be98935b','（2023）京民终6994号','王某与京北房屋经纪有限公司转租授权纠纷','court_bj2','合同纠纷','转租授权','2023-05-26','王某、京北房屋经纪有限公司','转租授权是本案主要争点。二房东签约后无法提供原出租人的转租同意，双方分别就主合同中存在禁止转租条款发表意见。','二房东签约后无法提供原出租人的转租同意。庭审材料显示，主合同中存在禁止转租条款。双方对合同相关条款的解释不一致。','转租授权取决于授权范围、材料来源和接收主体是否清楚。主合同中存在禁止转租条款。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,转租授权,书面证据,主合同中存在禁止转租条款');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_024dd97d4a','（2023）京民初7031号','赵某与瑞景物业管理有限公司经纪服务费纠纷','court_cy','合同纠纷','经纪服务费','2023-06-18','赵某、瑞景物业管理有限公司','案件发生在租赁履行期间。经纪人在签约前后对服务费口径表述不一致；与经纪服务费相关的材料包括平台页面和聊天记录显示收费项目发生变化。','经纪人在签约前后对服务费口径表述不一致。庭审材料显示，平台页面和聊天记录显示收费项目发生变化。双方对合同相关条款的解释不一致。','法院围绕经纪服务费审查书面条款、沟通时间和资金流，注意到平台页面和聊天记录显示收费项目发生变化。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,经纪服务费,书面证据,平台页面和聊天记录显示收费项目发生变化');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_051a8863e5','（2023）京民初7068号','陈某与海淀住房租赁管理有限公司定金性质纠纷','court_ft','合同纠纷','定金性质','2023-07-11','陈某、海淀住房租赁管理有限公司','陈某与海淀住房租赁管理有限公司对定金性质协商未果。已查明付款备注写作意向金，收据写作定金，双方争议退款条件，并有付款前后文本对款项用途表述不一致佐证。','付款备注写作意向金，收据写作定金，双方争议退款条件。庭审材料显示，付款前后文本对款项用途表述不一致。双方对合同相关条款的解释不一致。','主张定金性质的一方需说明计算方式和合同依据；现有证据中，付款前后文本对款项用途表述不一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持陈某的请求，具体金额以判决主文为准。','部分支持','租赁,定金性质,书面证据,付款前后文本对款项用途表述不一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_95b87ec01a','（2023）京仲7105号','周某与清河物业服务中心电器折旧纠纷','court_bjac','合同纠纷','电器折旧','2023-08-03','周某、清河物业服务中心','法院审理的核心是电器折旧。空调压缩机故障后出租方要求租客承担全部更换费，现有书面材料中包含检测报告认为设备已接近设计寿命。','空调压缩机故障后出租方要求租客承担全部更换费。庭审材料显示，检测报告认为设备已接近设计寿命。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断电器折旧责任。检测报告认为设备已接近设计寿命。','经调解，双方就电器折旧的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,电器折旧,书面证据,检测报告认为设备已接近设计寿命');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_ef1ea9f74a','（2023）京民初7142号','孙某与诚家房地产经纪中心维修垫付纠纷','court_cp','合同纠纷','维修垫付','2023-08-26','孙某、诚家房地产经纪中心','双方合同履行过程中出现维修垫付争议。热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议；证据链以报修工单显示故障发生后当天通知房东为主。','热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议。庭审材料显示，报修工单显示故障发生后当天通知房东。双方对合同相关条款的解释不一致。','处理维修垫付需要区分自然损耗、公共部位责任和不当使用。现有材料显示，报修工单显示故障发生后当天通知房东。','对有书面凭证支持的维修垫付主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,维修垫付,书面证据,报修工单显示故障发生后当天通知房东');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_02d281cae5','（2023）京民初7179号','刘某与上地公寓运营中心门禁变更纠纷','court_sjs','其他','门禁变更','2023-09-18','刘某、上地公寓运营中心','该案涉及门禁变更及相应费用承担。小区夜间关闭部分入口，租客认为通勤条件明显变化，提交的关键材料为物业公告说明入口调整属于阶段性管理措施。','小区夜间关闭部分入口，租客认为通勤条件明显变化。庭审材料显示，物业公告说明入口调整属于阶段性管理措施。双方对合同相关条款的解释不一致。','门禁变更的责任范围取决于变化是否可预见以及是否造成实际损失；物业公告说明入口调整属于阶段性管理措施。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,门禁变更,书面证据,物业公告说明入口调整属于阶段性管理措施');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_0a9943d94b','（2023）京民初7216号','高某与安居住房服务有限公司付款账户纠纷','court_hd','合同纠纷','付款账户','2023-10-11','高某、安居住房服务有限公司','高某与安居住房服务有限公司因付款账户发生争议。出租方临时要求改向个人账户付款，租客拒绝后产生争议。主要证据为原合同和历史流水均指向另一账户。','出租方临时要求改向个人账户付款，租客拒绝后产生争议。庭审材料显示，原合同和历史流水均指向另一账户。双方对合同相关条款的解释不一致。','付款账户应先看合同约定，再核对实际付款、退款条件和金额凭证。原合同和历史流水均指向另一账户。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,付款账户,书面证据,原合同和历史流水均指向另一账户');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_68e76082ee','（2023）京民初7253号','林某与明远资产管理有限公司租期衔接纠纷','court_xc','合同纠纷','租期衔接','2023-11-03','林某、明远资产管理有限公司','本案处理租期衔接问题：新租约起始日与旧租约终止日重叠；庭审中提交了双方对钥匙和租金按日结算未达成一致。','新租约起始日与旧租约终止日重叠。庭审材料显示，双方对钥匙和租金按日结算未达成一致。双方对合同相关条款的解释不一致。','法院围绕租期衔接审查书面条款、沟通时间和资金流，注意到双方对钥匙和租金按日结算未达成一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持林某的请求，具体金额以判决主文为准。','部分支持','租赁,租期衔接,书面证据,双方对钥匙和租金按日结算未达成一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_6ee2075393','（2023）京仲7290号','许某与京北房屋经纪有限公司提前解约纠纷','court_bjac','合同纠纷','提前解约','2023-11-26','许某、京北房屋经纪有限公司','京北房屋经纪有限公司与许某对提前解约的责任范围意见不一。查明事实为租客因工作地点变化提前退租，合同约定与补充协议表述不一致，证据包括双方邮件对解约通知期有不同理解。','租客因工作地点变化提前退租，合同约定与补充协议表述不一致。庭审材料显示，双方邮件对解约通知期有不同理解。双方对合同相关条款的解释不一致。','主张提前解约的一方需说明计算方式和合同依据；现有证据中，双方邮件对解约通知期有不同理解。','经调解，双方就提前解约的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,提前解约,书面证据,双方邮件对解约通知期有不同理解');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_8f4823cf89','（2023）京民初7327号','韩某与瑞景物业管理有限公司租赁登记纠纷','court_cp','合同纠纷','租赁登记','2023-12-19','韩某、瑞景物业管理有限公司','争议源于合同未约定由谁准备登记材料，入住后双方相互推诿。韩某据此主张处理租赁登记，并提交社区窗口清单能够说明所需材料。','合同未约定由谁准备登记材料，入住后双方相互推诿。庭审材料显示，社区窗口清单能够说明所需材料。双方对合同相关条款的解释不一致。','租赁登记取决于授权范围、材料来源和接收主体是否清楚。社区窗口清单能够说明所需材料。','双方应按合同及已核实履行事实承担相应责任。','部分支持韩某的请求，具体金额以判决主文为准。','部分支持','租赁,租赁登记,书面证据,社区窗口清单能够说明所需材料');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_9676f5a1e9','（2024）京民初7364号','杜某与海淀住房租赁管理有限公司看房承诺纠纷','court_sjs','合同纠纷','看房承诺','2024-01-11','杜某、海淀住房租赁管理有限公司','围绕看房承诺，双方确认租赁关系存在，但对费用和责任有分歧。经纪人口头承诺可养宠物，合同草案却明确禁止；录音、平台详情和草案内容彼此冲突。','经纪人口头承诺可养宠物，合同草案却明确禁止。庭审材料显示，录音、平台详情和草案内容彼此冲突。双方对合同相关条款的解释不一致。','法院围绕看房承诺核对承诺形成时间及书面记录，现有材料显示，录音、平台详情和草案内容彼此冲突。','经调解，双方就看房承诺的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,看房承诺,书面证据,录音、平台详情和草案内容彼此冲突');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_44a6cea75b','（2024）京民初7401号','顾某与清河物业服务中心外墙渗水纠纷','court_hd','合同纠纷','外墙渗水','2024-02-03','顾某、清河物业服务中心','顾某起诉要求解决外墙渗水。案件材料记载暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关，其中物业工单、气象记录和墙面照片能够相互印证。','暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关。庭审材料显示，物业工单、气象记录和墙面照片能够相互印证。双方对合同相关条款的解释不一致。','关于外墙渗水，工单、检测报告和现场照片比单方陈述更能还原经过；物业工单、气象记录和墙面照片能够相互印证。','对有书面凭证支持的外墙渗水主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,外墙渗水,书面证据,物业工单、气象记录和墙面照片能够相互印证');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_80c0a661a3','（2024）京民初7438号','叶某与诚家房地产经纪中心供暖结算纠纷','court_xc','合同纠纷','供暖结算','2024-02-26','叶某、诚家房地产经纪中心','供暖结算是本案主要争点。租期跨越供暖季，预收供暖费的退还方式没有写清，双方分别就缴费凭证和合同附件对结算周期记载不同发表意见。','租期跨越供暖季，预收供暖费的退还方式没有写清。庭审材料显示，缴费凭证和合同附件对结算周期记载不同。双方对合同相关条款的解释不一致。','供暖结算应先看合同约定，再核对实际付款、退款条件和金额凭证。缴费凭证和合同附件对结算周期记载不同。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,供暖结算,书面证据,缴费凭证和合同附件对结算周期记载不同');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_ccb887e0b8','（2024）京民终7475号','唐某与上地公寓运营中心钥匙交接纠纷','court_bj2','合同纠纷','钥匙交接','2024-03-20','唐某、上地公寓运营中心','案件发生在租赁履行期间。交房时钥匙数量与退租清单不一致；与钥匙交接相关的材料包括双方签字的交接单只列明三把钥匙。','交房时钥匙数量与退租清单不一致。庭审材料显示，双方签字的交接单只列明三把钥匙。双方对合同相关条款的解释不一致。','法院围绕钥匙交接核对承诺形成时间及书面记录，现有材料显示，双方签字的交接单只列明三把钥匙。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,钥匙交接,书面证据,双方签字的交接单只列明三把钥匙');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_19c1d8ad6e','（2024）京民初7512号','张某与安居住房服务有限公司押金返还纠纷','court_cy','合同纠纷','押金返还','2024-04-12','张某、安居住房服务有限公司','张某与安居住房服务有限公司对押金返还协商未果。已查明退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围，并有租客提交入住照片、退租视频和保洁票据佐证。','退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围。庭审材料显示，租客提交入住照片、退租视频和保洁票据。双方对合同相关条款的解释不一致。','主张押金返还的一方需说明计算方式和合同依据；现有证据中，租客提交入住照片、退租视频和保洁票据。','双方应按合同及已核实履行事实承担相应责任。','部分支持张某的请求，具体金额以判决主文为准。','部分支持','租赁,押金返还,书面证据,租客提交入住照片、退租视频和保洁票据');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_4fd6e52c45','（2024）京民初7549号','李某与明远资产管理有限公司噪声影响纠纷','court_ft','合同纠纷','噪声影响','2024-05-05','李某、明远资产管理有限公司','法院审理的核心是噪声影响。出租前未披露相邻施工，租客入住后主张影响正常居住，现有书面材料中包含施工公告和看房时间能够证明披露范围。','出租前未披露相邻施工，租客入住后主张影响正常居住。庭审材料显示，施工公告和看房时间能够证明披露范围。双方对合同相关条款的解释不一致。','判断噪声影响是否影响合同履行，需要比较看房时披露内容、公告时间和实际通行情况。施工公告和看房时间能够证明披露范围。','经调解，双方就噪声影响的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,噪声影响,书面证据,施工公告和看房时间能够证明披露范围');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_3fcd8a220e','（2024）京仲7586号','王某与京北房屋经纪有限公司租金调整纠纷','court_bjac','合同纠纷','租金调整','2024-05-28','王某、京北房屋经纪有限公司','双方合同履行过程中出现租金调整争议。续租报价在短期内多次变化，租客主张应按较早报价履行；证据链以邮件中未出现明确接受或签署记录为主。','续租报价在短期内多次变化，租客主张应按较早报价履行。庭审材料显示，邮件中未出现明确接受或签署记录。双方对合同相关条款的解释不一致。','法院围绕租金调整审查书面条款、沟通时间和资金流，注意到邮件中未出现明确接受或签署记录。','对有书面凭证支持的租金调整主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,租金调整,书面证据,邮件中未出现明确接受或签署记录');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_454cf32861','（2024）京民初7623号','赵某与瑞景物业管理有限公司搬家通道纠纷','court_cp','其他','搬家通道','2024-06-20','赵某、瑞景物业管理有限公司','该案涉及搬家通道及相应费用承担。物业临时封闭车库通道，租客增加搬运费用，提交的关键材料为公告发布时间晚于搬家公司预约时间。','物业临时封闭车库通道，租客增加搬运费用。庭审材料显示，公告发布时间晚于搬家公司预约时间。双方对合同相关条款的解释不一致。','搬家通道的责任范围取决于变化是否可预见以及是否造成实际损失；公告发布时间晚于搬家公司预约时间。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,搬家通道,书面证据,公告发布时间晚于搬家公司预约时间');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_fd38868857','（2024）京民初7660号','陈某与海淀住房租赁管理有限公司出租权限纠纷','court_sjs','合同纠纷','出租权限','2024-07-13','陈某、海淀住房租赁管理有限公司','陈某与海淀住房租赁管理有限公司因出租权限发生争议。签约人并非产权登记人，双方争议其是否取得有效委托。主要证据为委托书、产权材料和收款账户是争议焦点。','签约人并非产权登记人，双方争议其是否取得有效委托。庭审材料显示，委托书、产权材料和收款账户是争议焦点。双方对合同相关条款的解释不一致。','出租权限取决于授权范围、材料来源和接收主体是否清楚。委托书、产权材料和收款账户是争议焦点。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,出租权限,书面证据,委托书、产权材料和收款账户是争议焦点');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_e7f9c4b7cc','（2024）京民初7697号','周某与清河物业服务中心个人信息纠纷','court_hd','侵权责任','个人信息','2024-08-05','周某、清河物业服务中心','本案处理个人信息问题：经纪人要求提前发送身份证和收入证明，租客质疑收集范围；庭审中提交了机构未能说明资料保存期限和接收人员。','经纪人要求提前发送身份证和收入证明，租客质疑收集范围。庭审材料显示，机构未能说明资料保存期限和接收人员。双方对合同相关条款的解释不一致。','法院核对主体身份、授权文件和资料用途后处理个人信息；机构未能说明资料保存期限和接收人员。','双方应按合同及已核实履行事实承担相应责任。','部分支持周某的请求，具体金额以判决主文为准。','部分支持','租赁,个人信息,书面证据,机构未能说明资料保存期限和接收人员');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_ecfcbe586a','（2024）京民初7734号','孙某与诚家房地产经纪中心电器折旧纠纷','court_xc','合同纠纷','电器折旧','2024-08-28','孙某、诚家房地产经纪中心','诚家房地产经纪中心与孙某对电器折旧的责任范围意见不一。查明事实为空调压缩机故障后出租方要求租客承担全部更换费，证据包括检测报告认为设备已接近设计寿命。','空调压缩机故障后出租方要求租客承担全部更换费。庭审材料显示，检测报告认为设备已接近设计寿命。双方对合同相关条款的解释不一致。','关于电器折旧，工单、检测报告和现场照片比单方陈述更能还原经过；检测报告认为设备已接近设计寿命。','经调解，双方就电器折旧的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,电器折旧,书面证据,检测报告认为设备已接近设计寿命');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b4a2582632','（2024）京民终7771号','刘某与上地公寓运营中心维修垫付纠纷','court_bj2','合同纠纷','维修垫付','2024-09-20','刘某、上地公寓运营中心','争议源于热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议。刘某据此主张处理维修垫付，并提交报修工单显示故障发生后当天通知房东。','热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议。庭审材料显示，报修工单显示故障发生后当天通知房东。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断维修垫付责任。报修工单显示故障发生后当天通知房东。','对有书面凭证支持的维修垫付主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,维修垫付,书面证据,报修工单显示故障发生后当天通知房东');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_460627e666','（2024）京民初7808号','高某与安居住房服务有限公司门禁变更纠纷','court_cy','其他','门禁变更','2024-10-13','高某、安居住房服务有限公司','围绕门禁变更，双方确认租赁关系存在，但对费用和责任有分歧。小区夜间关闭部分入口，租客认为通勤条件明显变化；物业公告说明入口调整属于阶段性管理措施。','小区夜间关闭部分入口，租客认为通勤条件明显变化。庭审材料显示，物业公告说明入口调整属于阶段性管理措施。双方对合同相关条款的解释不一致。','法院结合物业公告、现场路线和新增费用审查门禁变更，其中物业公告说明入口调整属于阶段性管理措施。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,门禁变更,书面证据,物业公告说明入口调整属于阶段性管理措施');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_126ceda848','（2024）京民初7845号','林某与明远资产管理有限公司付款账户纠纷','court_ft','合同纠纷','付款账户','2024-11-05','林某、明远资产管理有限公司','林某起诉要求解决付款账户。案件材料记载出租方临时要求改向个人账户付款，租客拒绝后产生争议，其中原合同和历史流水均指向另一账户。','出租方临时要求改向个人账户付款，租客拒绝后产生争议。庭审材料显示，原合同和历史流水均指向另一账户。双方对合同相关条款的解释不一致。','主张付款账户的一方需说明计算方式和合同依据；现有证据中，原合同和历史流水均指向另一账户。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,付款账户,书面证据,原合同和历史流水均指向另一账户');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_35afb4ca42','（2024）京仲7882号','许某与京北房屋经纪有限公司租期衔接纠纷','court_bjac','合同纠纷','租期衔接','2024-11-28','许某、京北房屋经纪有限公司','租期衔接是本案主要争点。新租约起始日与旧租约终止日重叠，双方分别就双方对钥匙和租金按日结算未达成一致发表意见。','新租约起始日与旧租约终止日重叠。庭审材料显示，双方对钥匙和租金按日结算未达成一致。双方对合同相关条款的解释不一致。','租期衔接应先看合同约定，再核对实际付款、退款条件和金额凭证。双方对钥匙和租金按日结算未达成一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持许某的请求，具体金额以判决主文为准。','部分支持','租赁,租期衔接,书面证据,双方对钥匙和租金按日结算未达成一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_3a4aa30a7e','（2024）京民初7919号','韩某与瑞景物业管理有限公司家具损坏纠纷','court_xc','合同纠纷','家具损坏','2024-12-21','韩某、瑞景物业管理有限公司','案件发生在租赁履行期间。退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用；与家具损坏相关的材料包括交接照片显示铰链此前已有松动。','退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。庭审材料显示，交接照片显示铰链此前已有松动。双方对合同相关条款的解释不一致。','处理家具损坏需要区分自然损耗、公共部位责任和不当使用。现有材料显示，交接照片显示铰链此前已有松动。','经调解，双方就家具损坏的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,家具损坏,书面证据,交接照片显示铰链此前已有松动');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_f94abc2ef8','（2025）京民终7956号','杜某与海淀住房租赁管理有限公司物业维修纠纷','court_bj2','其他','物业维修','2025-01-13','杜某、海淀住房租赁管理有限公司','杜某与海淀住房租赁管理有限公司对物业维修协商未果。已查明公共排水堵塞造成室内返水，物业与出租方争议责任分担，并有维修记录显示堵点位于公共立管佐证。','公共排水堵塞造成室内返水，物业与出租方争议责任分担。庭审材料显示，维修记录显示堵点位于公共立管。双方对合同相关条款的解释不一致。','关于物业维修，工单、检测报告和现场照片比单方陈述更能还原经过；维修记录显示堵点位于公共立管。','对有书面凭证支持的物业维修主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,物业维修,书面证据,维修记录显示堵点位于公共立管');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_cb5d5eb600','（2025）京民初7993号','顾某与清河物业服务中心转租授权纠纷','court_cy','合同纠纷','转租授权','2025-02-05','顾某、清河物业服务中心','法院审理的核心是转租授权。二房东签约后无法提供原出租人的转租同意，现有书面材料中包含主合同中存在禁止转租条款。','二房东签约后无法提供原出租人的转租同意。庭审材料显示，主合同中存在禁止转租条款。双方对合同相关条款的解释不一致。','转租授权取决于授权范围、材料来源和接收主体是否清楚。主合同中存在禁止转租条款。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,转租授权,书面证据,主合同中存在禁止转租条款');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_8013b8f28a','（2025）京民初8030号','叶某与诚家房地产经纪中心经纪服务费纠纷','court_ft','合同纠纷','经纪服务费','2025-02-28','叶某、诚家房地产经纪中心','双方合同履行过程中出现经纪服务费争议。经纪人在签约前后对服务费口径表述不一致；证据链以平台页面和聊天记录显示收费项目发生变化为主。','经纪人在签约前后对服务费口径表述不一致。庭审材料显示，平台页面和聊天记录显示收费项目发生变化。双方对合同相关条款的解释不一致。','法院围绕经纪服务费审查书面条款、沟通时间和资金流，注意到平台页面和聊天记录显示收费项目发生变化。','对有书面凭证支持的经纪服务费主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,经纪服务费,书面证据,平台页面和聊天记录显示收费项目发生变化');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_9199d31487','（2025）京仲8067号','唐某与上地公寓运营中心定金性质纠纷','court_bjac','合同纠纷','定金性质','2025-03-23','唐某、上地公寓运营中心','该案涉及定金性质及相应费用承担。付款备注写作意向金，收据写作定金，双方争议退款条件，提交的关键材料为付款前后文本对款项用途表述不一致。','付款备注写作意向金，收据写作定金，双方争议退款条件。庭审材料显示，付款前后文本对款项用途表述不一致。双方对合同相关条款的解释不一致。','主张定金性质的一方需说明计算方式和合同依据；现有证据中，付款前后文本对款项用途表述不一致。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,定金性质,书面证据,付款前后文本对款项用途表述不一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_fc3f7e066a','（2025）京民初8104号','张某与安居住房服务有限公司清洁费用纠纷','court_cp','合同纠纷','清洁费用','2025-04-15','张某、安居住房服务有限公司','张某与安居住房服务有限公司因清洁费用发生争议。合同只写恢复整洁，退租时出租方主张高额深度清洁费。主要证据为出租方未提供实际清洁发票。','合同只写恢复整洁，退租时出租方主张高额深度清洁费。庭审材料显示，出租方未提供实际清洁发票。双方对合同相关条款的解释不一致。','清洁费用应先看合同约定，再核对实际付款、退款条件和金额凭证。出租方未提供实际清洁发票。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,清洁费用,书面证据,出租方未提供实际清洁发票');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_5c9b9bda49','（2025）京民初8141号','李某与明远资产管理有限公司押金返还纠纷','court_sjs','合同纠纷','押金返还','2025-05-08','李某、明远资产管理有限公司','本案处理押金返还问题：退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围；庭审中提交了租客提交入住照片、退租视频和保洁票据。','退租后出租方以墙面污渍为由扣除大部分押金，但交接单未记录污渍范围。庭审材料显示，租客提交入住照片、退租视频和保洁票据。双方对合同相关条款的解释不一致。','法院围绕押金返还审查书面条款、沟通时间和资金流，注意到租客提交入住照片、退租视频和保洁票据。','双方应按合同及已核实履行事实承担相应责任。','部分支持李某的请求，具体金额以判决主文为准。','部分支持','租赁,押金返还,书面证据,租客提交入住照片、退租视频和保洁票据');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_fc183b9ae9','（2025）京民初8178号','王某与京北房屋经纪有限公司噪声影响纠纷','court_hd','合同纠纷','噪声影响','2025-05-31','王某、京北房屋经纪有限公司','京北房屋经纪有限公司与王某对噪声影响的责任范围意见不一。查明事实为出租前未披露相邻施工，租客入住后主张影响正常居住，证据包括施工公告和看房时间能够证明披露范围。','出租前未披露相邻施工，租客入住后主张影响正常居住。庭审材料显示，施工公告和看房时间能够证明披露范围。双方对合同相关条款的解释不一致。','噪声影响的责任范围取决于变化是否可预见以及是否造成实际损失；施工公告和看房时间能够证明披露范围。','经调解，双方就噪声影响的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,噪声影响,书面证据,施工公告和看房时间能够证明披露范围');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_37bcb16379','（2025）京民初8215号','赵某与瑞景物业管理有限公司租金调整纠纷','court_xc','合同纠纷','租金调整','2025-06-23','赵某、瑞景物业管理有限公司','争议源于续租报价在短期内多次变化，租客主张应按较早报价履行。赵某据此主张处理租金调整，并提交邮件中未出现明确接受或签署记录。','续租报价在短期内多次变化，租客主张应按较早报价履行。庭审材料显示，邮件中未出现明确接受或签署记录。双方对合同相关条款的解释不一致。','租金调整应先看合同约定，再核对实际付款、退款条件和金额凭证。邮件中未出现明确接受或签署记录。','对有书面凭证支持的租金调整主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,租金调整,书面证据,邮件中未出现明确接受或签署记录');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_8a5bbbf269','（2025）京民终8252号','陈某与海淀住房租赁管理有限公司搬家通道纠纷','court_bj2','其他','搬家通道','2025-07-16','陈某、海淀住房租赁管理有限公司','围绕搬家通道，双方确认租赁关系存在，但对费用和责任有分歧。物业临时封闭车库通道，租客增加搬运费用；公告发布时间晚于搬家公司预约时间。','物业临时封闭车库通道，租客增加搬运费用。庭审材料显示，公告发布时间晚于搬家公司预约时间。双方对合同相关条款的解释不一致。','法院结合物业公告、现场路线和新增费用审查搬家通道，其中公告发布时间晚于搬家公司预约时间。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,搬家通道,书面证据,公告发布时间晚于搬家公司预约时间');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_d4a1eef2ff','（2025）京民初8289号','周某与清河物业服务中心出租权限纠纷','court_cy','合同纠纷','出租权限','2025-08-08','周某、清河物业服务中心','周某起诉要求解决出租权限。案件材料记载签约人并非产权登记人，双方争议其是否取得有效委托，其中委托书、产权材料和收款账户是争议焦点。','签约人并非产权登记人，双方争议其是否取得有效委托。庭审材料显示，委托书、产权材料和收款账户是争议焦点。双方对合同相关条款的解释不一致。','对于出租权限，不能只凭口头说明，应结合可追溯的书面材料。现有材料表明，委托书、产权材料和收款账户是争议焦点。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,出租权限,书面证据,委托书、产权材料和收款账户是争议焦点');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b885bf5e38','（2025）京民初8326号','孙某与诚家房地产经纪中心租赁登记纠纷','court_ft','合同纠纷','租赁登记','2025-08-31','孙某、诚家房地产经纪中心','租赁登记是本案主要争点。合同未约定由谁准备登记材料，入住后双方相互推诿，双方分别就社区窗口清单能够说明所需材料发表意见。','合同未约定由谁准备登记材料，入住后双方相互推诿。庭审材料显示，社区窗口清单能够说明所需材料。双方对合同相关条款的解释不一致。','租赁登记取决于授权范围、材料来源和接收主体是否清楚。社区窗口清单能够说明所需材料。','双方应按合同及已核实履行事实承担相应责任。','部分支持孙某的请求，具体金额以判决主文为准。','部分支持','租赁,租赁登记,书面证据,社区窗口清单能够说明所需材料');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_a61d7e88a5','（2025）京仲8363号','刘某与上地公寓运营中心看房承诺纠纷','court_bjac','合同纠纷','看房承诺','2025-09-23','刘某、上地公寓运营中心','案件发生在租赁履行期间。经纪人口头承诺可养宠物，合同草案却明确禁止；与看房承诺相关的材料包括录音、平台详情和草案内容彼此冲突。','经纪人口头承诺可养宠物，合同草案却明确禁止。庭审材料显示，录音、平台详情和草案内容彼此冲突。双方对合同相关条款的解释不一致。','法院围绕看房承诺核对承诺形成时间及书面记录，现有材料显示，录音、平台详情和草案内容彼此冲突。','经调解，双方就看房承诺的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,看房承诺,书面证据,录音、平台详情和草案内容彼此冲突');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_f74019c6f3','（2025）京民初8400号','高某与安居住房服务有限公司外墙渗水纠纷','court_cp','合同纠纷','外墙渗水','2025-10-16','高某、安居住房服务有限公司','高某与安居住房服务有限公司对外墙渗水协商未果。已查明暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关，并有物业工单、气象记录和墙面照片能够相互印证佐证。','暴雨后卧室墙面返潮，物业检查认为可能与外墙接缝有关。庭审材料显示，物业工单、气象记录和墙面照片能够相互印证。双方对合同相关条款的解释不一致。','关于外墙渗水，工单、检测报告和现场照片比单方陈述更能还原经过；物业工单、气象记录和墙面照片能够相互印证。','对有书面凭证支持的外墙渗水主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,外墙渗水,书面证据,物业工单、气象记录和墙面照片能够相互印证');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_694486b078','（2025）京民初8437号','林某与明远资产管理有限公司供暖结算纠纷','court_sjs','合同纠纷','供暖结算','2025-11-08','林某、明远资产管理有限公司','法院审理的核心是供暖结算。租期跨越供暖季，预收供暖费的退还方式没有写清，现有书面材料中包含缴费凭证和合同附件对结算周期记载不同。','租期跨越供暖季，预收供暖费的退还方式没有写清。庭审材料显示，缴费凭证和合同附件对结算周期记载不同。双方对合同相关条款的解释不一致。','供暖结算应先看合同约定，再核对实际付款、退款条件和金额凭证。缴费凭证和合同附件对结算周期记载不同。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,供暖结算,书面证据,缴费凭证和合同附件对结算周期记载不同');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_0d9b4f9830','（2025）京民初8474号','许某与京北房屋经纪有限公司钥匙交接纠纷','court_hd','合同纠纷','钥匙交接','2025-12-01','许某、京北房屋经纪有限公司','双方合同履行过程中出现钥匙交接争议。交房时钥匙数量与退租清单不一致；证据链以双方签字的交接单只列明三把钥匙为主。','交房时钥匙数量与退租清单不一致。庭审材料显示，双方签字的交接单只列明三把钥匙。双方对合同相关条款的解释不一致。','法院围绕钥匙交接核对承诺形成时间及书面记录，现有材料显示，双方签字的交接单只列明三把钥匙。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,钥匙交接,书面证据,双方签字的交接单只列明三把钥匙');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_66df55e931','（2025）京民初8511号','韩某与瑞景物业管理有限公司发票开具纠纷','court_xc','合同纠纷','发票开具','2025-12-24','韩某、瑞景物业管理有限公司','该案涉及发票开具及相应费用承担。机构收取服务费后长期未开具发票，提交的关键材料为付款记录和多次催办邮件可以核实。','机构收取服务费后长期未开具发票。庭审材料显示，付款记录和多次催办邮件可以核实。双方对合同相关条款的解释不一致。','主张发票开具的一方需说明计算方式和合同依据；现有证据中，付款记录和多次催办邮件可以核实。','双方应按合同及已核实履行事实承担相应责任。','部分支持韩某的请求，具体金额以判决主文为准。','部分支持','租赁,发票开具,书面证据,付款记录和多次催办邮件可以核实');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_4b747069db','（2026）京仲8548号','杜某与海淀住房租赁管理有限公司家具损坏纠纷','court_bjac','合同纠纷','家具损坏','2026-01-16','杜某、海淀住房租赁管理有限公司','杜某与海淀住房租赁管理有限公司因家具损坏发生争议。退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。主要证据为交接照片显示铰链此前已有松动。','退租时衣柜铰链损坏，双方争议属于自然损耗还是不当使用。庭审材料显示，交接照片显示铰链此前已有松动。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断家具损坏责任。交接照片显示铰链此前已有松动。','经调解，双方就家具损坏的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,家具损坏,书面证据,交接照片显示铰链此前已有松动');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_6cdeb86cf5','（2026）京民初8585号','顾某与清河物业服务中心物业维修纠纷','court_cp','其他','物业维修','2026-02-08','顾某、清河物业服务中心','本案处理物业维修问题：公共排水堵塞造成室内返水，物业与出租方争议责任分担；庭审中提交了维修记录显示堵点位于公共立管。','公共排水堵塞造成室内返水，物业与出租方争议责任分担。庭审材料显示，维修记录显示堵点位于公共立管。双方对合同相关条款的解释不一致。','处理物业维修需要区分自然损耗、公共部位责任和不当使用。现有材料显示，维修记录显示堵点位于公共立管。','对有书面凭证支持的物业维修主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,物业维修,书面证据,维修记录显示堵点位于公共立管');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_a8ace62045','（2026）京民初8622号','叶某与诚家房地产经纪中心转租授权纠纷','court_sjs','合同纠纷','转租授权','2026-03-03','叶某、诚家房地产经纪中心','诚家房地产经纪中心与叶某对转租授权的责任范围意见不一。查明事实为二房东签约后无法提供原出租人的转租同意，证据包括主合同中存在禁止转租条款。','二房东签约后无法提供原出租人的转租同意。庭审材料显示，主合同中存在禁止转租条款。双方对合同相关条款的解释不一致。','对于转租授权，不能只凭口头说明，应结合可追溯的书面材料。现有材料表明，主合同中存在禁止转租条款。','证据能够证明部分事实，但不足以支持全部请求。','驳回缺乏合同或损失凭证的诉讼请求。','驳回','租赁,转租授权,书面证据,主合同中存在禁止转租条款');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_d49a9f7068','（2026）京民初8659号','唐某与上地公寓运营中心经纪服务费纠纷','court_hd','合同纠纷','经纪服务费','2026-03-26','唐某、上地公寓运营中心','争议源于经纪人在签约前后对服务费口径表述不一致。唐某据此主张处理经纪服务费，并提交平台页面和聊天记录显示收费项目发生变化。','经纪人在签约前后对服务费口径表述不一致。庭审材料显示，平台页面和聊天记录显示收费项目发生变化。双方对合同相关条款的解释不一致。','经纪服务费应先看合同约定，再核对实际付款、退款条件和金额凭证。平台页面和聊天记录显示收费项目发生变化。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,经纪服务费,书面证据,平台页面和聊天记录显示收费项目发生变化');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_cca895974d','（2026）京民初8696号','张某与安居住房服务有限公司定金性质纠纷','court_xc','合同纠纷','定金性质','2026-04-18','张某、安居住房服务有限公司','围绕定金性质，双方确认租赁关系存在，但对费用和责任有分歧。付款备注写作意向金，收据写作定金，双方争议退款条件；付款前后文本对款项用途表述不一致。','付款备注写作意向金，收据写作定金，双方争议退款条件。庭审材料显示，付款前后文本对款项用途表述不一致。双方对合同相关条款的解释不一致。','法院围绕定金性质审查书面条款、沟通时间和资金流，注意到付款前后文本对款项用途表述不一致。','双方应按合同及已核实履行事实承担相应责任。','部分支持张某的请求，具体金额以判决主文为准。','部分支持','租赁,定金性质,书面证据,付款前后文本对款项用途表述不一致');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_4bc46fa365','（2026）京民终8733号','李某与明远资产管理有限公司电器折旧纠纷','court_bj2','合同纠纷','电器折旧','2026-05-11','李某、明远资产管理有限公司','李某起诉要求解决电器折旧。案件材料记载空调压缩机故障后出租方要求租客承担全部更换费，其中检测报告认为设备已接近设计寿命。','空调压缩机故障后出租方要求租客承担全部更换费。庭审材料显示，检测报告认为设备已接近设计寿命。双方对合同相关条款的解释不一致。','关于电器折旧，工单、检测报告和现场照片比单方陈述更能还原经过；检测报告认为设备已接近设计寿命。','现有材料不足以直接确认全部责任，相关请求另按证据处理。','对证据不足部分不作实体支持。','其他','租赁,电器折旧,书面证据,检测报告认为设备已接近设计寿命');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_34df46ed98','（2022）京民初8770号','王某与京北房屋经纪有限公司维修垫付纠纷','court_cy','合同纠纷','维修垫付','2022-01-05','王某、京北房屋经纪有限公司','维修垫付是本案主要争点。热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议，双方分别就报修工单显示故障发生后当天通知房东发表意见。','热水器在正常使用中故障，租客先行支付维修费，双方对报销比例发生争议。庭审材料显示，报修工单显示故障发生后当天通知房东。双方对合同相关条款的解释不一致。','法院结合故障原因、设备年限、报修时间和维修凭证判断维修垫付责任。报修工单显示故障发生后当天通知房东。','双方应按合同及已核实履行事实承担相应责任。','部分支持王某的请求，具体金额以判决主文为准。','部分支持','租赁,维修垫付,书面证据,报修工单显示故障发生后当天通知房东');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_43fe3b3da4','（2022）京民初8807号','赵某与瑞景物业管理有限公司门禁变更纠纷','court_ft','其他','门禁变更','2022-01-28','赵某、瑞景物业管理有限公司','案件发生在租赁履行期间。小区夜间关闭部分入口，租客认为通勤条件明显变化；与门禁变更相关的材料包括物业公告说明入口调整属于阶段性管理措施。','小区夜间关闭部分入口，租客认为通勤条件明显变化。庭审材料显示，物业公告说明入口调整属于阶段性管理措施。双方对合同相关条款的解释不一致。','法院结合物业公告、现场路线和新增费用审查门禁变更，其中物业公告说明入口调整属于阶段性管理措施。','经调解，双方就门禁变更的处理时间和金额达成一致。','确认双方调解协议有效并按约履行。','调解','租赁,门禁变更,书面证据,物业公告说明入口调整属于阶段性管理措施');
INSERT INTO cases(case_id,case_number,title,court_id,case_type,cause,judgment_date,parties,summary,facts,reasoning,holding,ruling,outcome,keywords) VALUES ('case_b891839b3d','（2022）京仲8844号','陈某与海淀住房租赁管理有限公司付款账户纠纷','court_bjac','合同纠纷','付款账户','2022-02-20','陈某、海淀住房租赁管理有限公司','陈某与海淀住房租赁管理有限公司对付款账户协商未果。已查明出租方临时要求改向个人账户付款，租客拒绝后产生争议，并有原合同和历史流水均指向另一账户佐证。','出租方临时要求改向个人账户付款，租客拒绝后产生争议。庭审材料显示，原合同和历史流水均指向另一账户。双方对合同相关条款的解释不一致。','主张付款账户的一方需说明计算方式和合同依据；现有证据中，原合同和历史流水均指向另一账户。','对有书面凭证支持的付款账户主张予以审查；缺少金额依据的部分不予确认。','支持有充分凭证的请求，其余请求驳回。','支持','租赁,付款账户,书面证据,原合同和历史流水均指向另一账户');
